8next';\n\nimport { PATHS } from '@/consts';\nimport { useModal, usePillarContext } from '@/context';\n\ntype WalletErrorModalProps = {\n  error: unknown;\n  onSumbit?: () => void;\n  title?: string;\n  buttonText?: string;\n  dataTestId?: string;\n};\n\nexport const useWalletErrorModal = () => {\n  const { t } = useTranslation();\n  const { useRouter } = usePillarContext();\n  const router = useRouter();\n  const { openModal, closeModal } = useModal();\n\n  const openWalletErrorModal = ({\n    error,\n    onSumbit,\n    title,\n    buttonText,\n    dataTestId,\n  }: WalletErrorModalProps) => {\n    const errorMessage =\n      error && typeof error === 'object' && 'info' in error\n        ? error.info\n        : error;\n\n    openModal({\n      type: 'statusModal',\n      state: {\n        status: 'warning',\n        title: title ?? t('modals.common.oops'),\n        message: errorMessage,\n        buttonText: buttonText ?? t('modals.common.goToDashboard'),\n        onSubmit: () => {\n          if (onSumbit) onSumbit();\n          else router.push(PATHS.dashboard);\n          closeModal();\n        },\n        dataTestId: dataTestId ?? 'wallet-error-modal',\n      },\n    });\n  };\n\n  return openWalletErrorModal;\n};\n","import { useCallback, useState } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport * as Sentry from '@sentry/react';\n\nimport { usePillarContext } from '@/context';\nimport { useGetVoterInfo } from '../queries/useGetVoterInfoQuery';\nimport { useWalletErrorModal } from '../modal/useWalletErrorModal';\n\nexport const useDelegateTodRep = () => {\n  const {\n    buildSignSubmitConwayCertTx,\n    buildVoteDelegationCert,\n    buildDRepRetirementCert,\n    addSuccessAlert,\n    addErrorAlert,\n  } = usePillarContext();\n  const { t } = useTranslation();\n  const openWalletErrorModal = useWalletErrorModal();\n  const { voter } = useGetVoterInfo();\n\n  const [isDelegating, setIsDelegating] = useState<string | null>(null);\n\n  const delegate = useCallback(\n    async (dRepId: string | undefined) => {\n      if (!dRepId) return;\n      setIsDelegating(dRepId);\n      try {\n        if (voter?.isRegisteredAsSoleVoter && !voter?.deposit) {\n          throw new Error(t('errors.appCannotGetDeposit'));\n        }\n\n        const certBuilder = await buildVoteDelegationCert(dRepId);\n        if (voter?.isRegisteredAsSoleVoter) {\n          const retirementCert = await buildDRepRetirementCert(\n            voter?.deposit?.toString()\n          );\n          certBuilder.add(retirementCert);\n        }\n        await buildSignSubmitConwayCertTx({\n          certBuilder,\n          type: 'delegate',\n          resourceId: dRepId,\n          voter,\n        });\n      } catch (error) {\n        openWalletErrorModal({\n          error,\n          buttonText: t('cancel'),\n          onSumbit: () => {},\n          dataTestId: 'delegate-transaction-error-modal',\n        });\n        Sentry.setTag('hook', 'useDelegateTodRep');\n        Sentry.captureException(error);\n      } finally {\n        setIsDelegating(null);\n      }\n    },\n    [\n      addErrorAlert,\n      addSuccessAlert,\n      buildSignSubmitConwayCertTx,\n      buildVoteDelegationCert,\n      t,\n      voter?.deposit,\n      voter?.isRegisteredAsSoleVoter,\n    ]\n  );\n\n  return {\n    delegate,\n    isDelegating,\n  };\n};\n","import { useCallback, useState } from 'react';\nimport * as Sentry from '@sentry/react';\n\nimport { usePillarContext } from '@/context';\nimport {\n  useActionSuccessModal,\n  useGetVoterInfo,\n  useWalletErrorModal,\n} from '@/hooks';\n\ntype MetadataInfo = {\n  hash: string;\n  uri: string;\n};\n\nexport const useRegisterVoter = () => {\n  const {\n    buildSignSubmitConwayCertTx,\n    buildDRepRegCert,\n    buildDRepUpdateCert,\n    buildVoteDelegationCert,\n    dRepID,\n  } = usePillarContext();\n  const openActionSuccessModal = useActionSuccessModal();\n  const openWalletErrorModal = useWalletErrorModal();\n  const { voter } = useGetVoterInfo();\n\n  const [isLoading, setIsLoading] = useState(false);\n\n  const registerVoter = useCallback(\n    async (metadata?: MetadataInfo) => {\n      setIsLoading(true);\n      if (metadata && !metadata.hash) return;\n\n      const builderArgs = metadata ? [metadata.uri, metadata.hash] : [];\n\n      try {\n        const certBuilder = await buildVoteDelegationCert(dRepID);\n        const registerCert = voter?.isRegisteredAsDRep\n          ? await buildDRepUpdateCert(...builderArgs)\n          : await buildDRepRegCert(...builderArgs);\n        certBuilder.add(registerCert);\n\n        const result = await buildSignSubmitConwayCertTx({\n          certBuilder,\n          type: metadata ? 'registerAsDrep' : 'registerAsDirectVoter',\n        });\n        if (result)\n          openActionSuccessModal({ action: 'registration', link: result });\n      } catch (error: any) {\n        Sentry.setTag(\n          'hook',\n          `useRegisterAs${metadata ? 'DRep' : 'DirectVoter'}`\n        );\n        Sentry.captureException(error);\n\n        openWalletErrorModal({\n          error,\n          dataTestId: 'registration-transaction-error-modal',\n        });\n      } finally {\n        setIsLoading(false);\n      }\n    },\n    [\n      buildSignSubmitConwayCertTx,\n      buildDRepRegCert,\n      dRepID,\n      voter?.isRegisteredAsDRep,\n    ]\n  );\n\n  return {\n    registerVoter,\n    isRegistering: isLoading,\n  };\n};\n","import { useCallback, useState } from 'react';\n\nimport { usePillarContext } from '@/context';\nimport {\n  useActionSuccessModal,\n  useGetVoterInfo,\n  useTranslation,\n  useWalletErrorModal,\n} from '@/hooks';\n\nexport const useRetireVoter = () => {\n  const {\n    isPendingTransaction,\n    buildSignSubmitConwayCertTx,\n    buildDRepRetirementCert,\n  } = usePillarContext();\n  const { t } = useTranslation();\n  const openActionSuccessModal = useActionSuccessModal();\n  const openWalletErrorModal = useWalletErrorModa