    textTransform: 'none',\n        },\n        outlined: (props) => ({\n          borderColor: props.theme.palette.lightBlue,\n        }),\n      },\n    },\n    MuiChip: {\n      variants: [\n        {\n          props: { color: 'default', variant: 'filled' },\n          style: {\n            backgroundColor: primaryBlue.c50,\n          },\n        },\n        {\n          props: { color: 'success', variant: 'filled' },\n          style: {\n            backgroundColor: successGreen.c200,\n            color: successGreen.c700,\n          },\n        },\n        {\n          props: { color: 'error', variant: 'filled' },\n          style: {\n            backgroundColor: errorRed.c100,\n            color: errorRed.c500,\n          },\n        },\n        {\n          props: { color: 'warning', variant: 'filled' },\n          style: {\n            backgroundColor: progressYellow.c200,\n            color: orange.c700,\n          },\n        },\n        {\n          props: { color: 'info', variant: 'filled' },\n          style: {\n            backgroundColor: cyan.c100,\n            color: cyan.c500,\n          },\n        },\n      ],\n      styleOverrides: {\n        root: {\n          fontSize: '0.875rem',\n          fontWeight: 500,\n          height: 28,\n        },\n        filledPrimary: {\n          backgroundColor: primaryBlue.c100,\n          color: primaryBlue.c500,\n        },\n        filledSecondary: {\n          backgroundColor: orange.c100,\n          color: orange.c600,\n        },\n      },\n    },\n    MuiLink: {\n      styleOverrides: {\n        root: {\n          cursor: 'pointer',\n        },\n      },\n    },\n    MuiPaper: {\n      styleOverrides: {\n        root: {\n          borderRadius: 12,\n        },\n      },\n    },\n    MuiPopover: {\n      defaultProps: {\n        elevation: 2,\n      },\n    },\n  },\n  typography: {\n    fontFamily: 'Poppins, Arial',\n    allVariants: {\n      color: '#242232',\n    },\n  },\n  palette: {\n    accentOrange: '#F29339',\n    accentYellow: '#F2D9A9',\n    arcticWhite: '#FBFBFF',\n    boxShadow1: 'rgba(0, 18, 61, 0.37)',\n    boxShadow2: 'rgba(47, 98, 220, 0.2)',\n    errorRed: '#9E2323',\n    fadedPurple: '#716E88',\n    highlightBlue: '#C2EFF299',\n    inputRed: '#FAEAEB',\n    lightBlue: '#D6E2FF',\n    lightOrange: '#FFCBAD',\n    negativeRed: '#E58282',\n    neutralGray: '#8E908E',\n    neutralWhite: '#FFFFFF',\n    orangeDark: '#803205',\n    positiveGreen: '#5CC165',\n    primary: { main: '#0033AD' },\n    primaryBlue: '#0033AD',\n    secondary: { main: 'rgb(255, 100, 10)' },\n    secondaryBlue: '#6F99FF',\n    specialCyan: '#1C94B2',\n    specialCyanBorder: '#77BFD1',\n    textBlack: '#242232',\n    textGray: '#525252',\n  },\n});\n\ntheme.shadows[1] =\n  '0px 1px 2px 0px rgba(0, 51, 173, 0.08), 0px 1px 6px 1px rgba(0, 51, 173, 0.15)';\ntheme.shadows[2] =\n  '0px 1px 2px 0px rgba(0, 51, 173, 0.08), 0px 2px 10px 2px rgba(0, 51, 173, 0.15)';\ntheme.shadows[3] =\n  '0px 1px 3px 0px rgba(0, 51, 173, 0.08), 0px 4px 12px 3px rgba(0, 51, 173, 0.15)';\ntheme.shadows[4] =\n  '0px 2px 3px 0px rgba(0, 51, 173, 0.08), 0px 6px 14px 4px rgba(0, 51, 173, 0.15)';\ntheme.shadows[5] =\n  '0px 4px 4px 0px rgba(0, 51, 173, 0.08), 0px 8px 20px 6px rgba(0, 51, 173, 0.15)';\n\nexport default theme;\n","import type { TypographyProps as MUITypographyProps } from '@mui/material';\nimport { Typography as MUITypography } from '@mui/material';\n\nexport type TypographyProps = Pick<\n  MUITypographyProps,\n  'color' | 'lineHeight' | 'sx' | 'component'\n> & {\n  children?: React.ReactNode;\n  fontSize?: number;\n  fontWeight?: 100 | 200 | 300 | 400 | 500 | 600 | 700 | 800 | 900;\n  variant?:\n    | 'headline1'\n    | 'headline2'\n    | 'headline3'\n    | 'headline4'\n    | 'headline5'\n    | 'title1'\n    | 'title2'\n    | 'body1'\n    | 'body2'\n    | 'caption';\n};\n\nexport const Typography = ({\n  color,\n  variant = 'body1',\n  ...props\n}: TypographyProps) => {\n  const fontSize = {\n    headline1: 100,\n    headline2: 57,\n    headline3: 36,\n    headline4: 32,\n    headline5: 28,\n    title1: 24,\n    title2: 22,\n    body1: 16,\n    body2: 14,\n    caption: 12,\n  }[variant];\n\n  const fontWeight = {\n    headline1: 600,\n    headline2: 700,\n    headline3: 400,\n    headline4: 600,\n    headline5: 500,\n    title1: 400,\n    title2: 500,\n    body1: 600,\n    body2: 500,\n    caption: 400,\n  }[variant];\n\n  const lineHeight = {\n    headline1: '110px',\n    headline2: '57px',\n    headline3: '44px',\n    headline4: '40px',\n    headline5: '36px',\n    title1: '32px',\n    title2: '28px',\n    body1: '24px',\n    body2: '20px',\n    caption: '16px',\n  }[variant];\n\n  return (\n    <MUITypography\n      color={color}\n      fontSize={fontSize}\n      fontWeight={fontWeight}\n      lineHeight={lineHeight}\n      {...props}\n    >\n      {props.children}\n    </MUITypography>\n  );\n};\n","import { forwardRef, useCallback, useImperativeHandle, useRef } from 'react';\nimport type { TextareaAutosizeProps } from '@mui/material';\nimport { TextareaAutosize, styled } from '@mui/material';\n\nimport { useScreenDimension } from '@/hooks';\n\nexport type TextAreaProps = TextareaAutosizeProps & {\n  errorMessage?: string;\n  isModifiedLayout?: boolean;\n};\n\nconst TextAreaBase = styled(TextareaAutosize)(\n  () => `\n  font-family: \"Poppins\";\n  font-weight: 400;\n    ::placeholder {\n      font-family: \"Poppins\";\n      font-weight: 400;\n      color: #a6a6a6;\n    }\n    `\n);\n\nexport const TextArea = forwardRef<HTMLTextAreaElement, TextAreaProps>(\n  (\n    {\n      errorMessage,\n      maxLength = 500,\n      onBlur,\n      onFocus,\n      isModifiedLayout,\n      ...props\n    },\n    ref\n  ) => {\n    const { isMobile } = useScreenDimension();\n    const textAraeRef = useRef<HTMLTextAreaElement>(null);\n\n    const handleFocus = useCallback(\n      (e: React.FocusEvent<HTMLTextAreaElement>) => {\n        onFocus?.(e);\n        textAraeRef.current?.focus();\n      },\n      []\n    );\n\n    const handleBlur = useCallback(\n      (e: React.FocusEvent<HTMLTextAreaElement>) => {\n        onBlur?.(e);\n        textAraeRef.current?.blur();\n      },\n      []\n    );\n\n    useImperativeHandle(\n      ref,\n      () =>\n        ({\n          focus: handleFocus,\n          blur: handleBlur,\n          ...textAraeRef.current,\n        }) as unknown as HTMLTextAreaElement,\n      [handleBlur, handleFocus]\n    );\n\n    const getTexAreaHeight = () => {\n      if (isModifiedLayout && isMobile) return '312px';\n      if (isModifiedLayout) return '208px';\n      if (isMobile) return '104px';\n      return '128px';\n    };\n\n    return (\n      <TextAreaBase\n        style={{\n          border: `1px solid ${errorMessage ? 'red' : '#6F99FF'}`,\n          backgroundColor: errorMessage ? '#FAEAEB' : 'white',\n          borderRadius: '24px',\n          height: getTexAreaHeight(),\n          outline: 'none',\n          padding: '12px 14px',\n          resize: 'none',\n        }}\n        maxLength={maxLength}\n        ref={textAraeRef}\n        sx={{\n          fontSize: isModifiedLayout ? '12px' : 'auto',\n          '&::placeholder': {\n            fontSize: isModifiedLayout ? '12px' : '16px',\n          },\n        }}\n        {...props}\n      />\n    );\n  }\n);\n","import type { TypographyProps } from '../Typography';\nimport { Typography } from '../Typography';\n\nexport type FormHelpfulTextProps = {\n  dataTestId?: string;\n  helpfulText?: string;\n  sx?: TypographyProps['sx'];\n};\n\nexport const FormHelpfulText = ({\n  dataTestId,\n  helpfulText,\n  sx,\n}: FormHelpfulTextProps) => {\n  if (!helpfulText) return null;\n\n  return (\n    <Typography\n      color=\"#9792B5\"\n      data-testid={\n        dataTestId ?? `${helpfulText.replace(/\\s+/g, '-').toLowerCase()}-error`\n      }\n      fontSize={12}\n      fontWeight={400}\n      sx={{ mt: 0.5, ...sx }}\n    >\n      {helpfulText}\n    </Typography>\n  );\n};\n","import type { TypographyProps } from '../Typography';\nimport { Typography } from '../Typography';\n\nexport type FormErrorMessageProps = {\n  dataTestId?: string;\n  errorMessage?: string;\n  sx?: TypographyProps;\n};\n\nexport const FormErrorMessage = ({\n  dataTestId,\n  errorMessage,\n  sx,\n}: FormErrorMessageProps) => {\n  if (!errorMessage) return null;\n\n  return (\n    <Typography\n      color=\"red\"\n      data-testid={\n        dataTestId ?? `${errorMessage.replace(/\\s+/g, '-').toLowerCase()}-error`\n      }\n      fontSize={12}\n      fontWeight={400}\n      sx={{ mt: 0.25, ...sx }}\n    >\n      {errorMessage}\n    </Typography>\n  );\n};\n","import { useCallback } from 'react';\nimport type { BoxProps } from '@mui/material';\nimport { Box } from '@mui/material';\n\nimport { Checkbox as CheckboxBase, CheckboxProps } from '../input';\nimport { Typography, TypographyProps } from '../Typography';\nimport { FormHelpfulText } from './FormHelpfulText';\nimport { FormErrorMessage } from './FormErrorMessage';\n\nexport type CheckboxFieldProps = CheckboxProps & {\n  errorMessage?: string;\n  errorStyles?: TypographyProps;\n  helpfulText?: string;\n  helpfulTextStyle?: TypographyProps;\n  label?: string;\n  labelStyles?: TypographyProps;\n  layoutStyles?: BoxProps;\n};\n\nexport const Checkbox = ({\n  errorMessage,\n  errorStyles,\n  helpfulText,\n  helpfulTextStyle,\n  label,\n  labelStyles,\n  layoutStyles,\n  onChange,\n  value,\n  ...rest\n}: CheckboxFieldProps) => {\n  const handleValue = useCallback(() => {\n    onChange(!value);\n  }, [value]);\n\n  return (\n    <Box sx={{ width: '100%', ...layoutStyles }}>\n      <Box\n        onClick={handleValue}\n        sx={{\n          alignItems: 'center',\n          cursor: 'pointer',\n          display: 'grid',\n          gridTemplateColumns: 'auto 1fr',\n          gridTemplateAreas: '\"checkbox label\" \". helpfulText\"',\n          width: 'fit-content',\n        }}\n      >\n        <CheckboxBase\n          {...{ onChange, value }}\n          errorMessage={errorMessage}\n          {...rest}\n        />\n        {label && (\n          <Typography variant=\"caption\" {...labelStyles}>\n            {label}\n          </Typography>\n        )}\n        <FormHelpfulText\n          helpfulText={helpfulText}\n          sx={{ gridArea: 'helpfulText', ...helpfulTextStyle }}\n        />\n      </Box>\n      <FormErrorMessage errorMessage={errorMessage} sx={errorStyles} />\n    </Box>\n  );\n};\n","import { forwardRef, useCallback, useImperativeHandle, useRef } from 'react';\nimport type { BoxProps } from '@mui/material';\nimport { Box } from '@mui/material';\n\nimport { testIdFromLabel } from '@/utils';\nimport { Input as InputBase, InputProps } from '../input';\nimport { Typography, TypographyProps } from '../Typography';\nimport { FormHelpfulText } from './FormHelpfulText';\nimport { FormErrorMessage } from './FormErrorMessage';\n\nexport type InputFieldProps = InputProps & {\n  errorDataTestId?: string;\n  errorMessage?: string;\n  errorStyles?: TypographyProps;\n  helpfulTextDataTestId?: string;\n  helpfulText?: string;\n  helpfulTextStyle?: TypographyProps;\n  label?: string;\n  labelStyles?: TypographyProps;\n  layoutStyles?: BoxProps;\n};\n\nexport const Input = forwardRef<HTMLInputElement, InputFieldProps>(\n  (\n    {\n      errorDataTestId,\n      errorMessage,\n      errorStyles,\n      helpfulTextDataTestId,\n      helpfulText,\n      helpfulTextStyle,\n      label,\n      labelStyles,\n      layoutStyles,\n      onBlur,\n      onFocus,\n      ...rest\n    },\n    ref\n  ) => {\n    const inputRef = useRef<HTMLInputElement>(null);\n\n    const handleFocus = useCallback((e: React.FocusEvent<HTMLInputElement>) => {\n      onFocus?.(e);\n      inputRef.current?.focus();\n    }, []);\n\n    const handleBlur = useCallback((e: React.FocusEvent<HTMLInputElement>) => {\n      onBlur?.(e);\n      inputRef.current?.blur();\n    }, []);\n\n    useImperativeHandle(\n      ref,\n      () =>\n        ({\n          focus: handleFocus,\n          blur: handleBlur,\n          ...inputRef.current,\n        }) as unknown as HTMLInputElement,\n      [handleBlur, handleFocus]\n    );\n\n    return (\n      <Box sx={{ width: '100%', ...layoutStyles }}>\n        {label && (\n          <Typography\n            fontWeight={400}\n            sx={{ mb: 0.5 }}\n            variant=\"body2\"\n            {...labelStyles}\n          >\n            {label}\n          </Typography>\n        )}\n        <InputBase\n          dataTestId={\n            rest.dataTestId ?? `${label && `${testIdFromLabel(label)}-`}input`\n          }\n          errorMessage={errorMessage}\n          {...rest}\n          ref={inputRef}\n        />\n        <FormHelpfulText\n          dataTestId={helpfulTextDataTestId}\n          helpfulText={helpfulText}\n          sx={helpfulTextStyle}\n        />\n        <FormErrorMessage\n          dataTestId={errorDataTestId}\n          errorMessage={errorMessage}\n          sx={errorStyles}\n        />\n      </Box>\n    );\n  }\n);\n","import { forwardRef, useCallback, useImperativeHandle, useRef } from 'react';\nimport type { BoxProps } from '@mui/material';\nimport { Box } from '@mui/material';\n\nimport { TextArea as TextAreaBase, TextAreaProps } from '../input';\nimport { Typography, TypographyProps } from '../Typography';\nimport { FormHelpfulText } from './FormHelpfulText';\nimport { FormErrorMessage } from './FormErrorMessage';\n\nexport type TextAreaFieldProps = TextAreaProps & {\n  errorMessage?: string;\n  errorStyles?: TypographyProps;\n  helpfulText?: string;\n  helpfulTextStyle?: TypographyProps;\n  hideLabel?: boolean;\n  label?: string;\n  labelStyles?: TypographyProps;\n  layoutStyles?: BoxProps;\n};\n\nexport const TextArea = forwardRef<HTMLTextAreaElement, TextAreaFieldProps>(\n  (\n    {\n      errorMessage,\n      errorStyles,\n      helpfulText,\n      helpfulTextStyle,\n      hideLabel,\n      label,\n      labelStyles,\n      layoutStyles,\n      maxLength = 500,\n      onBlur,\n      onFocus,\n      ...props\n    },\n    ref\n  ) => {\n    const textAreaRef = useRef<HTMLTextAreaElement>(null);\n\n    const handleFocus = useCallback(\n      (e: React.FocusEvent<HTMLTextAreaElement>) => {\n        onFocus?.(e);\n        textAreaRef.current?.focus();\n      },\n      []\n    );\n\n    const handleBlur = useCallback(\n      (e: React.FocusEvent<HTMLTextAreaElement>) => {\n        onBlur?.(e);\n        textAreaRef.current?.blur();\n      },\n      []\n    );\n\n    useImperativeHandle(\n      ref,\n      () =>\n        ({\n          focus: handleFocus,\n          blur: handleBlur,\n          ...textAreaRef.current,\n        }) as unknown as HTMLTextAreaElement,\n      [handleBlur, handleFocus]\n    );\n\n    return (\n      <Box\n        sx={{\n          display: 'flex',\n          flexDirection: 'column',\n          width: '100%',\n          position: 'relative',\n          ...layoutStyles,\n        }}\n      >\n        {label && (\n          <Typography\n            fontWeight={400}\n            sx={{ mb: 0.5, ...(hideLabel && { fontSize: 0, lineHeight: 0 }) }}\n            variant=\"body2\"\n            {...labelStyles}\n          >\n            {label}\n          </Typography>\n        )}\n        <Box\n          sx={{\n            display: 'flex',\n            flexDirection: 'column',\n            position: 'relative',\n          }}\n        >\n          <TextAreaBase\n            errorMessage={errorMessage}\n            maxLength={maxLength}\n            {...props}\n            ref={textAreaRef}\n          />\n          <Typography\n            color=\"#8E908E\"\n            sx={{\n              bottom: 12,\n              position: 'absolute',\n              right: 14,\n            }}\n            variant=\"caption\"\n          >\n            {props?.value?.toString()?.length ?? 0}/{maxLength}\n          </Typography>\n        </Box>\n        <FormHelpfulText helpfulText={helpfulText} sx={helpfulTextStyle} />\n        <FormErrorMessage errorMessage={errorMessage} sx={errorStyles} />\n      </Box>\n    );\n  }\n);\n","import React, { PropsWithChildren } from 'react';\n\nimport { Checkbox } from './Checkbox';\nimport { Input } from './Input';\nimport { TextArea } from './TextArea';\n\ntype FieldComposition = React.FC<PropsWithChildren> & {\n  Input: typeof Input;\n  Checkbox: typeof Checkbox;\n  TextArea: typeof TextArea;\n};\n\nconst Field: FieldComposition = ({ children }) => children as any;\n\nField.Checkbox = Checkbox;\nField.Input = Input;\nField.TextArea = TextArea;\n\nexport { Field };\n\nexport * from './Checkbox';\nexport * from './Input';\nexport * from './TextArea';\n","import { useCallback } from 'react';\nimport { Controller, get } from 'react-hook-form';\n\nimport { CheckboxFieldProps, Field } from '../field';\nimport { ControlledFieldProps, RenderInputProps } from './types';\n\nexport type ControlledCheckboxProps = ControlledFieldProps &\n  Omit<CheckboxFieldProps, 'onChange' | 'value'>;\n\nexport const Checkbox = ({\n  control,\n  name,\n  errors,\n  rules,\n  ...props\n}: ControlledCheckboxProps) => {\n  const errorMessage = get(errors, name)?.message as string;\n\n  const renderInput = useCallback(\n    ({ field }: RenderInputProps) => (\n      <Field.Checkbox\n        checked={!!field.value}\n        errorMessage={errorMessage}\n        name={field.name}\n        onChange={field.onChange}\n        value={field.value}\n        {...props}\n      />\n    ),\n    [errorMessage, props]\n  );\n\n  return (\n    <Controller\n      name={name}\n      control={control}\n      rules={rules}\n      render={renderInput}\n    />\n  );\n};\n","import { forwardRef, useCallback } from 'react';\nimport { Controller, get } from 'react-hook-form';\n\nimport { InputFieldProps, Field } from '../field';\nimport { ControlledFieldProps, RenderInputProps } from './types';\n\ntype ControlledInputProps = ControlledFieldProps & InputFieldProps;\n\nexport const Input = forwardRef<HTMLInputElement, ControlledInputProps>(\n  ({ control, name, errors, rules, ...props }, ref) => {\n    const errorMessage = get(errors, name)?.message as string;\n\n    const renderInput = useCallback(\n      ({ field }: RenderInputProps) => (\n        <Field.Input\n          {...props}\n          {...field}\n          errorMessage={errorMessage}\n          ref={ref}\n        />\n      ),\n      [errorMessage, props]\n    );\n\n    return (\n      <Controller\n        name={name}\n        control={control}\n        rules={rules}\n        render={renderInput}\n      />\n    );\n  }\n);\n","import { useCallback } from 'react';\nimport { Controller, get } from 'react-hook-form';\n\nimport { TextAreaFieldProps, Field } from '../field';\nimport { ControlledFieldProps, RenderInputProps } from './types';\n\ntype ControlledTextAreaProps = ControlledFieldProps & TextAreaFieldProps;\n\nexport const TextArea = ({\n  control,\n  name,\n  errors,\n  rules,\n  ...props\n}: ControlledTextAreaProps) => {\n  const errorMessage = get(errors, name)?.message as string;\n\n  const renderInput = useCallback(\n    ({ field }: RenderInputProps) => (\n      <Field.TextArea {...props} {...field} errorMessage={errorMessage} />\n    ),\n    [errorMessage, props]\n  );\n\n  return (\n    <Controller\n      name={name}\n      control={control}\n      rules={rules}\n      render={renderInput}\n    />\n  );\n};\n","import React, { PropsWithChildren } from 'react';\n\nimport { Checkbox } from './Checkbox';\nimport { Input } from './Input';\nimport { TextArea } from './TextArea';\n\ntype ControlledFieldComposition = React.FC<PropsWithChildren> & {\n  Checkbox: typeof Checkbox;\n  Input: typeof Input;\n  TextArea: typeof TextArea;\n};\n\nconst ControlledField: ControlledFieldComposition = ({ children }) => (\n  <>{children}</>\n);\n\nControlledField.Checkbox = Checkbox;\nControlledField.Input = Input;\nControlledField.TextArea = TextArea;\n\nexport { ControlledField };\n","import { forwardRef } from 'react';\nimport { SxProps, styled } from '@mui/material/styles';\n\nimport { ICONS } from '@/consts';\nimport { useModal } from '@/context';\nimport { callAll } from '@/utils';\n\ninterface Props {\n  variant?: 'modal' | 'popup';\n  onClose?: () => void;\n  hideCloseButton?: boolean;\n  children: React.ReactNode;\n  dataTestId?: string;\n  sx?: SxProps;\n}\n\nexport const BaseWrapper = styled('div')<Pick<Props, 'variant'>>`\n  box-shadow: 1px 2px 11px 0px #00123d5e;\n  max-height: 90vh;\n  position: fixed;\n  top: 50%;\n  left: 50%;\n  display: flex;\n  flex-direction: column;\n  background: #fbfbff;\n  border-radius: 24px;\n  transform: translate(-50%, -50%);\n\n  ${({ variant }) => {\n    if (variant === 'modal') {\n      return `\n        width: 80vw;\n        max-width: 510px;\n        padding: 52px 24px 34px 24px;\n        max-height: 80vh;\n        overflow: auto;\n      `;\n    }\n    if (variant === 'popup') {\n      return `\n        width: 320px;\n        height: 320px;\n      `;\n    }\n  }}\n`;\n\nexport const CloseButton = styled('img')`\n  cursor: pointer;\n  position: absolute;\n  top: 24px;\n  right: 24px;\n`;\n\nexport const ModalWrapper = forwardRef<HTMLDivElement, Props>(\n  (\n    {\n      children,\n      onClose,\n      variant = 'modal',\n      hideCloseButton = false,\n      dataTestId = 'modal',\n      sx,\n    },\n    ref\n  ) => {\n    const { closeModal } = useModal();\n\n    return (\n      <BaseWrapper variant={variant} data-testid={dataTestId} sx={sx} ref={ref}>\n        {variant !== 'popup' && !hideCloseButton && (\n          <CloseButton\n            data-testid=\"close-modal-button\"\n            alt=\"close\"\n            onClick={callAll(closeModal, onClose)}\n            src={ICONS.closeIcon}\n          />\n        )}\n        {children}\n      </BaseWrapper>\n    );\n  }\n);\n","import Typography from '@mui/material/Typography';\nimport type { SxProps } from '@mui/system';\n\ninterface Props {\n  children: React.ReactNode;\n  sx?: SxProps;\n}\n\nexport const ModalHeader = ({ children, sx }: Props) => (\n  <Typography\n    marginBottom=\"8px\"\n    fontSize=\"28px\"\n    fontWeight=\"500\"\n    textAlign=\"center\"\n    sx={sx}\n  >\n    {children}\n  </Typography>\n);\n","import { Box } from '@mui/material';\nimport { useScreenDimension } from '@/hooks';\n\ninterface Props {\n  children: React.ReactNode;\n}\n\nexport const ModalContents = ({ children }: Props) => {\n  const { isMobile } = useScreenDimension();\n\n  return (\n    <Box\n      display=\"flex\"\n      flexDirection=\"column\"\n      alignItems=\"center\"\n      px={isMobile ? 0 : 3}\n    >\n      {children}\n    </Box>\n  );\n};\n","import { forwardRef } from 'react';\nimport { Box, Button, Typography } from '@mui/material';\n\nimport { IMAGES } from '@/consts';\nimport { useModal } from '@/context';\nimport { useScreenDimension, useTranslation } from '@/hooks';\nimport { voltaireTheme as theme } from '@/theme';\n\nimport { ModalWrapper } from './ModalWrapper';\nimport { ModalHeader } from './ModalHeader';\nimport { ModalContents } from './ModalContents';\n\nexport interface ExternalLinkModalState {\n  externalLink: string;\n}\n\nexport const ExternalLinkModal = forwardRef<HTMLDivElement>((_, ref) => {\n  const { state, closeModal } = useModal<ExternalLinkModalState>();\n  const { isMobile } = useScreenDimension();\n  const { t } = useTranslation();\n  const {\n    palette: { primaryBlue, fadedPurple },\n  } = theme;\n\n  return (\n    <ModalWrapper dataTestId=\"external-link-modal\" ref={ref}>\n      <img\n        alt=\"Status icon\"\n        src={IMAGES.warningYellowImage}\n        style={{ height: '84px', margin: '0 auto', width: '84px' }}\n      />\n      <ModalHeader sx={{ marginTop: '34px' }}>\n        {t(`modals.externalLink.${isMobile ? 'safety' : 'beCareful'}`)}\n      </ModalHeader>\n      <ModalContents>\n        <Typography textAlign=\"center\" sx={{ fontSize: '16px' }}>\n          {t(\n            `modals.externalLink.${isMobile ? 'thisIs' : 'youAreAboutToOpen'}`\n          )}\n        </Typography>\n        <Typography\n          textAlign=\"center\"\n          sx={{\n            fontSize: '16px',\n            marginBottom: '38px',\n            color: primaryBlue,\n            textDecoration: 'underline',\n            wordBreak: 'break-word',\n          }}\n        >\n          {state?.externalLink}\n        </Typography>\n        <Typography\n          textAlign=\"center\"\n          sx={{\n            fontSize: isMobile ? '16px' : '14px',\n            marginBottom: '38px',\n            color: fadedPurple,\n          }}\n        >\n          {t('modals.externalLink.description')}\n        </Typography>\n      </ModalContents>\n      <Box\n        sx={{\n          alignItems: 'center',\n          display: 'flex',\n          justifyContent: 'center',\n          gap: '38px',\n        }}\n      >\n        <Button\n          data-testid=\"continue-modal-button\"\n          href={state?.externalLink ?? ''}\n          target=\"_blank\"\n          onClick={closeModal}\n          sx={{\n            borderRadius: 50,\n            textTransform: 'none',\n            height: '40px',\n          }}\n          variant=\"contained\"\n        >\n          {t(`${isMobile ? 'continue' : 'modals.externalLink.continueTo'}`)}\n        </Button>\n        <Button\n          data-testid=\"cancel-modal-button\"\n          onClick={() => {\n            closeModal();\n          }}\n          sx={{\n            borderRadius: 50,\n            padding: '10px 26px',\n            textTransform: 'none',\n            height: '40px',\n            width: '117px',\n          }}\n          variant=\"outlined\"\n        >\n          {t('cancel')}\n        </Button>\n      </Box>\n    </ModalWrapper>\n  );\n});\n","import { forwardRef } from 'react';\nimport { Typography } from '@mui/material';\n\nimport { useModal } from '@/context';\nimport { useScreenDimension } from '@/hooks';\nimport { ICONS } from '@/consts';\n\nimport { ModalWrapper } from './ModalWrapper';\nimport { ModalHeader } from './ModalHeader';\nimport { ModalContents } from './ModalContents';\n\nexport interface LoadingModalState {\n  message: React.ReactNode;\n  title: string;\n  dataTestId: string;\n}\n\nexport const LoadingModal = forwardRef<HTMLDivElement>((_, ref) => {\n  const { state } = useModal<LoadingModalState>();\n  const { isMobile } = useScreenDimension();\n\n  return (\n    <ModalWrapper\n      dataTestId={state ? state.dataTestId : 'loading-modal'}\n      hideCloseButton\n      ref={ref}\n    >\n      <div style={{ width: 100, height: 100, margin: '0 auto' }}>\n        <img\n          src={ICONS.loaderIcon}\n          style={{ animation: `spin 2s linear infinite` }}\n          alt=\"loader\"\n        />\n      </div>\n      <ModalHeader sx={{ marginTop: '34px', px: isMobile ? 0 : 3 }}>\n        {state?.title}\n      </ModalHeader>\n      <ModalContents>\n        <Typography\n          textAlign=\"center\"\n          sx={{ fontSize: '16px', fontWeight: '400' }}\n        >\n          {state?.message}{' '}\n        </Typography>\n      </ModalContents>\n    </ModalWrapper>\n  );\n});\n","import { forwardRef } from 'react';\nimport { Button, Link, Typography } from '@mui/material';\n\nimport { ICONS, IMAGES } from '@/consts';\nimport { useModal, usePillarContext } from '@/context';\nimport { useScreenDimension, useTranslation } from '@/hooks';\n\nimport { ModalWrapper } from './ModalWrapper';\nimport { ModalHeader } from './ModalHeader';\nimport { ModalContents } from './ModalContents';\n\nexport interface StatusModalState {\n  buttonText?: string;\n  cancelText?: string;\n  feedbackText?: string;\n  status: 'warning' | 'info' | 'success';\n  isInfo?: boolean;\n  link?: string;\n  linkText?: string;\n  message: React.ReactNode;\n  onSubmit?: () => void;\n  onCancel?: () => void;\n  onFeedback?: () => void;\n  title: string;\n  dataTestId: string;\n}\n\nexport const StatusModal = forwardRef<HTMLDivElement>((_, ref) => {\n  const { state, closeModal } = useModal<StatusModalState>();\n  const { isMobile } = useScreenDimension();\n  const { t } = useTranslation();\n  const { openFeedbackWindow } = usePillarContext();\n\n  const onClickFeedback = () => {\n    openFeedbackWindow();\n    closeModal();\n  };\n\n  return (\n    <ModalWrapper\n      dataTestId={state ? state.dataTestId : 'status-modal'}\n      ref={ref}\n    >\n      <img\n        alt=\"Status icon\"\n        src={\n          state?.status === 'warning'\n            ? IMAGES.warningImage\n            : state?.status === 'success'\n              ? IMAGES.successImage\n              : ICONS.timerIcon\n        }\n        style={{ height: '84px', margin: '0 auto', width: '84px' }}\n      />\n      <ModalHeader sx={{ marginTop: '34px', px: isMobile ? 0 : 3 }}>\n        {state?.title}\n      </ModalHeader>\n      <ModalContents>\n        <Typography\n          textAlign=\"center\"\n          sx={{\n            fontSize: '16px',\n            fontWeight: '400',\n            overflow: 'hidden',\n            display: '-webkit-box',\n            WebkitBoxOrient: 'vertical',\n            WebkitLineClamp: 8,\n            wordBreak: 'break-word',\n            whiteSpace: 'pre-line',\n          }}\n        >\n          {state?.message}{' '}\n          {state?.link && (\n            <Link href={state.link} target=\"_blank\">\n              {state.linkText || t('thisLink')}\n            </Link>\n          )}\n        </Typography>\n      </ModalContents>\n      <Button\n        data-testid=\"confirm-modal-button\"\n        onClick={state?.onSubmit ? state?.onSubmit : closeModal}\n        sx={{\n          borderRadius: 50,\n          margin: '0 auto',\n          padding: '10px 26px',\n          textTransform: 'none',\n          marginTop: '38px',\n          width: '100%',\n        }}\n        variant=\"contained\"\n      >\n        {state?.buttonText || t('confirm')}\n      </Button>\n      {state?.cancelText && (\n        <Button\n          data-testid=\"cancel-modal-button\"\n          onClick={state?.onCancel ? state?.onCancel : closeModal}\n          sx={{\n            borderRadius: 50,\n            margin: '0 auto',\n            padding: '10px 26px',\n            textTransform: 'none',\n            marginTop: '24px',\n            width: '100%',\n          }}\n          variant=\"outlined\"\n        >\n          {state?.cancelText}\n        </Button>\n      )}\n      {state?.feedbackText && (\n        <Button\n          data-testid=\"feedback-button\"\n          onClick={state?.onFeedback ? state?.onFeedback : onClickFeedback}\n          sx={{\n            borderRadius: 50,\n            margin: '0 auto',\n            padding: '10px 26px',\n            textTransform: 'none',\n            marginTop: '24px',\n            width: '100%',\n          }}\n          variant=\"outlined\"\n        >\n          {state?.feedbackText}\n        </Button>\n      )}\n    </ModalWrapper>\n  );\n});\n","import type { ButtonProps as MUIButtonProps } from '@mui/material';\nimport { CircularProgress, Button as MUIButton } from '@mui/material';\n\nexport type ButtonProps = Omit<MUIButtonProps, 'size'> & {\n  isLoading?: boolean;\n  size?: 'small' | 'medium' | 'large' | 'extraLarge';\n  dataTestId?: string;\n  target?: string;\n};\n\nexport const Button = ({\n  size = 'large',\n  variant = 'contained',\n  sx,\n  isLoading,\n  ...props\n}: ButtonProps) => {\n  const height = {\n    extraLarge: 48,\n    large: 40,\n    medium: 36,\n    small: 32,\n  }[size];\n\n  const px = {\n    extraLarge: 3.5,\n    large: 3.25,\n    medium: 3,\n    small: 3,\n  }[size];\n\n  return (\n    <MUIButton\n      sx={{\n        fontSize: size === 'extraLarge' ? 16 : 14,\n        height,\n        px,\n        whiteSpace: 'nowrap',\n        ...sx,\n      }}\n      variant={variant}\n      {...props}\n      disabled={isLoading || props?.disabled}\n    >\n      {isLoading && (\n        <CircularProgress size={26} sx={{ position: 'absolute' }} />\n      )}\n      {props.children}\n    </MUIButton>\n  );\n};\n","import { Chip, Paper, SxProps } from '@mui/material';\nimport { Theme } from '@mui/material/styles';\nimport { PropsWithChildren } from 'react';\n\nimport { errorRed, orange, primaryBlue, successGreen } from '@/theme';\n\ntype CardProps = PropsWithChildren & {\n  border?: boolean;\n  elevation?: number;\n  dataTestId?: string;\n  label?: string;\n  labelDataTestId?: string;\n  sx?: SxProps<Theme>;\n  variant?: 'default' | 'error' | 'primary' | 'success' | 'warning';\n  onCardClick?: () => void;\n};\n\nconst COLORS = {\n  default: {\n    backgroundColor: undefined,\n    borderColor: primaryBlue.c100,\n  },\n  warning: {\n    backgroundColor: undefined,\n    borderColor: orange.c500,\n  },\n  error: {\n    backgroundColor: `${errorRed.c50}80`,\n    borderColor: errorRed.c100,\n  },\n  primary: {\n    backgroundColor: `${primaryBlue.c100}40`,\n    borderColor: primaryBlue.c500,\n  },\n  success: {\n    backgroundColor: undefined,\n    borderColor: successGreen.c500,\n  },\n} as const;\n\nexport const Card = ({\n  variant = 'default',\n  border = variant !== 'default',\n  dataTestId,\n  children,\n  elevation = 3,\n  label,\n  labelDataTestId = 'card-label',\n  sx,\n  onCardClick,\n}: CardProps) => {\n  const colors = COLORS[variant];\n\n  return (\n    <Paper\n      elevation={elevation}\n      data-testid={dataTestId}\n      onClick={onCardClick}\n      sx={{\n        backgroundColor: (theme) =>\n          colors.backgroundColor ?? `${theme.palette.neutralWhite}4D`,\n        border: border ? 1 : 0,\n        borderColor: colors?.borderColor,\n        padding: 3,\n        position: 'relative',\n        ...sx,\n      }}\n    >\n      {label && (\n        <Chip\n          data-testid={labelDataTestId}\n          color={variant}\n          label={label}\n          sx={{\n            position: 'absolute',\n            right: 30,\n            top: -15,\n          }}\n        />\n      )}\n      {children}\n    </Paper>\n  );\n};\n","import type { BoxProps } from '@mui/material';\nimport { Box, CircularProgress } from '@mui/material';\n\ntype Props = {\n  sx?: BoxProps['sx'];\n};\n\nexport const CircularLoader = ({ sx }: Props) => (\n  <Box\n    sx={{\n      display: 'flex',\n      flex: 1,\n      height: '100%',\n      alignItems: 'center',\n      justifyContent: 'center',\n      ...sx,\n    }}\n  >\n    <CircularProgress />\n  </Box>\n);\n","import { SxProps, Typography } from '@mui/material';\n\nimport { ICONS } from '@/consts';\nimport { useModal } from '@/context';\nimport { Button } from './Button';\n\nexport const ExternalModalButton = ({\n  label,\n  sx,\n  url,\n}: {\n  label: string;\n  url: string;\n  sx?: SxProps;\n}) => {\n  const { openModal } = useModal();\n\n  return (\n    <Button\n      onClick={() => {\n        openModal({\n          type: 'externalLink',\n          state: {\n            externalLink: url,\n          },\n        });\n      }}\n      sx={{\n        p: 0,\n        mb: 4,\n        ':hover': {\n          backgroundColor: 'transparent',\n        },\n        ...sx,\n      }}\n      disableRipple\n      variant=\"text\"\n      data-testid=\"external-modal-button\"\n    >\n      <Typography variant=\"body1\" fontWeight={500} color=\"primary\">\n        {label}\n      </Typography>\n      <img\n        alt=\"external link\"\n        src={ICONS.externalLinkIcon}\n        height=\"20\"\n        width=\"20\"\n        style={{ marginLeft: '8px' }}\n      />\n    </Button>\n  );\n};\n","import { MouseEvent, useState } from 'react';\nimport { Box, ButtonBase, Popover } from '@mui/material';\n\nimport { ICONS } from '@/consts';\nimport { useTranslation } from '@/hooks';\nimport { usePillarContext } from '@/context';\nimport { Typography } from './Typography';\n\nexport const Share = ({ link }: { link: string }) => {\n  const { addSuccessAlert } = usePillarContext();\n  const { t } = useTranslation();\n  const [anchorEl, setAnchorEl] = useState<HTMLButtonElement | null>(null);\n  const [isActive, setIsActive] = useState<boolean>(true);\n\n  const handleClick = (event: MouseEvent<HTMLButtonElement>) => {\n    setAnchorEl(event.currentTarget);\n  };\n\n  const handleClose = () => {\n    setAnchorEl(null);\n  };\n\n  const onCopy = (event: MouseEvent<HTMLButtonElement>) => {\n    navigator.clipboard.writeText(link);\n    addSuccessAlert(t('alerts.copiedToClipboard'));\n    setIsActive(false);\n    event.stopPropagation();\n  };\n\n  const open = Boolean(anchorEl);\n  const id = open ? 'simple-popover' : undefined;\n\n  return (\n    <>\n      <ButtonBase\n        data-testid=\"share-button\"\n        aria-describedby={id}\n        onClick={handleClick}\n        sx={(theme) => ({\n          alignItems: 'center',\n          bgcolor: open ? '#F7F9FB' : 'transparent',\n          borderRadius: 50,\n          boxShadow: open ? theme.shadows[1] : 'none',\n          cursor: 'pointer',\n          display: 'flex',\n          justifyContent: 'center',\n          padding: 1.5,\n          transition: 'all 0.3s',\n          '&:hover': {\n            boxShadow: theme.shadows[1],\n            bgcolor: '#F7F9FB',\n          },\n        })}\n      >\n        <img alt=\"\" height={24} width={24} src={ICONS.share} />\n      </ButtonBase>\n      <Popover\n        id={id}\n        open={open}\n        onClose={handleClose}\n        anchorEl={anchorEl}\n        marginThreshold={12}\n        anchorOrigin={{\n          vertical: 'bottom',\n          horizontal: 'right',\n        }}\n        transformOrigin={{\n          vertical: 'top',\n          horizontal: 'right',\n        }}\n      >\n        <Box\n          sx={{\n            alignItems: 'center',\n            boxSizing: 'border-box',\n            display: 'flex',\n            flexDirection: 'column',\n            justifyContent: 'center',\n            padding: '12px 24px',\n            px: 3,\n            width: 148,\n          }}\n        >\n          <Typography sx={{ alignSelf: 'flex-start' }}>{t('share')}</Typography>\n          <ButtonBase\n            data-testid=\"copy-link-from-share-button\"\n            onClick={onCopy}\n            sx={{\n              alignItems: 'center',\n              bgcolor: isActive ? 'lightBlue' : 'neutralWhite',\n              borderRadius: 50,\n              boxShadow: (theme) => theme.shadows[1],\n              cursor: 'pointer',\n              display: 'flex',\n              height: 48,\n              justifyContent: 'center',\n              width: 48,\n              mt: 1.5,\n              mb: 1,\n            }}\n          >\n            <img alt=\"link\" height={24} src={ICONS.link} width={24} />\n          </ButtonBase>\n          <Typography variant=\"caption\">\n            {isActive ? t('clickToCopyLink') : t('linkCopied')}\n          </Typography>\n        </Box>\n      </Popover>\n    </>\n  );\n};\n","import { Box } from '@mui/material';\n\nexport type SpacerProps = {\n  x?: number;\n  y?: number;\n};\n\nexport const Spacer = ({ x, y }: SpacerProps) => <Box pt={y} pr={x} />;\n","export const LINKS = {\n  COMPATIBLE_WALLETS:\n    'https://docs.gov.tools/cardano-govtool/using-govtool/getting-started/compatible-wallets',\n};\n","export const openInNewTab = (url: string) => {\n  // Ensure the URL is absolute\n  const fullUrl =\n    url.startsWith('http://') || url.startsWith('https://')\n      ? url\n      : url.startsWith('ipfs')\n        ? `${import.meta.env.VITE_IPFS_GATEWAY}/${url.slice(7)}`\n        : `https://${url}`;\n\n  // eslint-disable-next-line no-console\n  console.debug('Opening in new tab', fullUrl);\n\n  // Open the URL in a new tab\n  const newWindow = window.open(fullUrl, '_blank', 'noopener,noreferrer');\n  if (newWindow) newWindow.opener = null;\n};\n","import { FC, useCallback } from 'react';\nimport { To, useNavigate, useLocation } from 'react-router-dom';\nimport { Box, CircularProgress, Typography } from '@mui/material';\nimport { usePillarContext } from '@/context';\nimport theme from '@/theme/voltaire';\nimport { PATHS } from '@/consts';\n\nexport interface WalletOption {\n  icon: string;\n  label: string;\n  name: string;\n  cip95Available: boolean;\n  dataTestId?: string;\n  pathToNavigate?: To;\n}\n\nexport const WalletOptionButton: FC<WalletOption> = ({\n  dataTestId,\n  icon,\n  label,\n  name,\n  cip95Available,\n  pathToNavigate,\n}) => {\n  const { isEnableLoading, enable } = usePillarContext();\n  const { pathname, hash, state } = useLocation();\n  const {\n    palette: { lightBlue },\n  } = theme;\n  const navigate = useNavigate();\n\n  const enableByWalletName = useCallback(async () => {\n    if (isEnableLoading) return;\n\n    const result = await enable(name);\n\n    if (result?.stakeKey) {\n      navigate(\n        // eslint-disable-next-line no-unneeded-ternary\n        pathToNavigate\n          ? pathToNavigate\n          : pathname === '/'\n            ? '/dashboard'\n            : `connected${pathname}${hash ?? ''}`,\n        { state }\n      );\n      return;\n    }\n    navigate(PATHS.stakeKeys);\n  }, [enable, isEnableLoading]);\n\n  return (\n    <Box\n      data-testid={dataTestId}\n      sx={{\n        alignItems: 'center',\n        border: isEnableLoading ? 'none' : `1px solid ${lightBlue}`,\n        bgcolor: isEnableLoading ? '#EAE9F0' : 'white',\n        borderRadius: '100px',\n        boxShadow: isEnableLoading ? undefined : '0px 0px 11px 0px #24223230',\n        boxSizing: 'border-box',\n        cursor: cip95Available\n          ? isEnableLoading\n            ? 'default'\n            : 'pointer'\n          : 'unset',\n        display: 'flex',\n        justifyContent: 'space-between',\n        marginBottom: '16px',\n        padding: '12px 13px 12px 13px',\n        transition: 'background .2s',\n        position: 'relative',\n        width: '100%',\n        '&:hover': isEnableLoading\n          ? undefined\n          : {\n              background: lightBlue,\n            },\n      }}\n      key={name}\n      onClick={enableByWalletName}\n    >\n      <img\n        alt={`${name} icon`}\n        src={icon}\n        style={{\n          height: '24px',\n          width: '24px',\n          filter: isEnableLoading ? 'grayscale(100%)' : 'none',\n        }}\n      />\n      <Typography\n        color={isEnableLoading ? '#C1BED3' : 'primaryBlue'}\n        sx={{\n          fontSize: '16px',\n          fontWeight: '500',\n        }}\n      >\n        {name ?? label}\n      </Typography>\n      <div style={{ height: '24px', width: '24px' }} />\n      {isEnableLoading === name && (\n        <Box\n          position=\"absolute\"\n          left={0}\n          right={0}\n          display=\"flex\"\n          justifyContent=\"center\"\n        >\n          <CircularProgress size={26} />\n        </Box>\n      )}\n    </Box>\n  );\n};\n","import { Box, Link, Typography } from '@mui/material';\nimport { forwardRef, useMemo } from 'react';\n\n// import type { WalletOption } from '@molecules';\n// import { WalletOptionButton } from '@molecules';\n// import { openInNewTab } from '@utils';\n// import { useTranslation } from '@hooks';\nimport { To } from 'react-router-dom';\nimport { ModalWrapper } from './ModalWrapper';\nimport { ModalHeader } from './ModalHeader';\nimport { ModalContents } from './ModalContents';\nimport { useModal } from '@/context';\nimport { LINKS } from '@/consts/links';\nimport { useTranslation } from '@/hooks';\nimport { openInNewTab } from '@/utils/openInNewTab';\nimport { WalletOption, WalletOptionButton } from '../WalletOptionButton';\n\ntype ChooseWalletModalState = {\n  pathToNavigate?: To;\n};\n\nexport const ChooseWalletModal = forwardRef<HTMLDivElement>((_, ref) => {\n  const { t } = useTranslation();\n  const { state } = useModal<ChooseWalletModalState>();\n  console.log('state', state);\n\n  const walletOptions: WalletOption[] = useMemo(() => {\n    if (!window.cardano) return [];\n    const keys = Object.keys(window.cardano);\n    const resultWallets: WalletOption[] = [];\n    keys.forEach((k: string) => {\n      const { icon, name, supportedExtensions } = window.cardano[k];\n      if (icon && name && supportedExtensions) {\n        // Check if the name already exists in resultWallets\n        const isNameDuplicate = resultWallets.some(\n          (wallet) => wallet.label === name\n        );\n        // Check if the supportedExtensions array contains an entry with cip === 95\n        const isCip95Available = Boolean(\n          supportedExtensions?.find((i) => i.cip === 95)\n        );\n        // If the name is not a duplicate and cip === 95 is available, add it to resultWallets\n        if (!isNameDuplicate && isCip95Available) {\n          resultWallets.push({\n            icon,\n            label: name,\n            name: k,\n            cip95Available: true,\n          });\n        }\n      }\n    });\n    return resultWallets;\n  }, [window]);\n\n  return (\n    <ModalWrapper dataTestId=\"connect-your-wallet-modal\" ref={ref}>\n      <ModalHeader>{t('wallet.connectYourWallet')}</ModalHeader>\n      <ModalContents>\n        <Typography\n          sx={{\n            fontSize: '16px',\n            fontWeight: '500',\n            marginBottom: '24px',\n            textAlign: 'center',\n          }}\n        >\n          {t('wallet.chooseWallet')}\n        </Typography>\n        <Box\n          sx={{\n            display: 'flex',\n            flexDirection: 'column',\n            maxHeight: '500px',\n            overflow: 'auto',\n            width: '100%',\n            padding: '8px',\n          }}\n        >\n          {!walletOptions.length ? (\n            <Typography\n              color=\"primary\"\n              variant=\"body2\"\n              fontWeight={600}\n              sx={{ textAlign: 'center' }}\n            >\n              {t('wallet.noWalletsToConnect')}\n            </Typography>\n          ) : (\n            walletOptions.map(({ icon, label, name, cip95Available }) => (\n              <WalletOptionButton\n                dataTestId={`${name}-wallet-button`}\n                key={name}\n                icon={icon}\n                label={label}\n                name={name}\n                cip95Available={cip95Available}\n                pathToNavigate={state?.pathToNavigate}\n              />\n            ))\n          )}\n        </Box>\n        <Typography\n          sx={{\n            fontSize: '11px',\n            fontWeight: '500',\n            marginTop: '24px',\n            textAlign: 'center',\n          }}\n        >\n          {t('wallet.cantSeeWalletQuestion')}\n          <Link\n            fontSize={11}\n            fontWeight={500}\n            onClick={() => openInNewTab(LINKS.COMPATIBLE_WALLETS)}\n            sx={{ cursor: 'pointer' }}\n          >\n            {t('here')}\n          </Link>\n          .\n        </Typography>\n      </ModalContents>\n    </ModalWrapper>\n  );\n});\n","import { createContext, useContext, useMemo, useReducer } from 'react';\n\nimport {\n  MuiModalChildren,\n  ExternalLinkModal,\n  StatusModal,\n  LoadingModal,\n} from '@/components';\nimport { basicReducer, callAll, BasicReducer } from '@/utils';\nimport { ChooseWalletModal } from '@/components/modal/ChooseWalletModal';\n\ninterface ProviderProps {\n  children: React.ReactNode;\n}\n\ninterface ContextModal {\n  component: MuiModalChildren | null;\n  variant?: 'modal' | 'popup';\n  preventDismiss?: boolean;\n  onClose?: () => void;\n}\n\nexport type ModalType =\n  | 'none'\n  | 'loadingModal'\n  | 'statusModal'\n  | 'externalLink'\n  | 'chooseWallet';\n\nconst modals: Record<ModalType, ContextModal> = {\n  none: {\n    component: null,\n  },\n  loadingModal: {\n    component: <LoadingModal />,\n  },\n  statusModal: {\n    component: <StatusModal />,\n  },\n  externalLink: {\n    component: <ExternalLinkModal />,\n  },\n  chooseWallet: {\n    component: <ChooseWalletModal />,\n  },\n};\n\ntype Optional<T, K extends keyof T> = Pick<Partial<T>, K> & Omit<T, K>;\n\nexport interface ModalState<T> {\n  type: ModalType;\n  state: T | null;\n}\n\ninterface ModalContextType<T> {\n  modal: ModalState<T>;\n  modals: Record<ModalType, ContextModal>;\n  state: T | null;\n  openModal: (modal: Optional<ModalState<T>, 'state'>) => void;\n  closeModal: () => void;\n}\n\n// eslint-disable-next-line @typescript-eslint/no-explicit-any\nconst ModalContext = createContext<ModalContextType<any>>(\n  {} as ModalContextType<unknown>\n);\nModalContext.displayName = 'ModalContext';\n\n// eslint-disable-next-line react/function-component-definition\nfunction ModalProvider<T>({ children, ...props }: ProviderProps) {\n  const [modal, openModal] = useReducer<BasicReducer<ModalState<T>>>(\n    basicReducer,\n    {\n      state: null,\n      type: 'none',\n    }\n  );\n\n  const value = useMemo(\n    () => ({\n      modals,\n      modal,\n      state: modal.state,\n      openModal,\n      closeModal: callAll(modals[modal.type]?.onClose, () =>\n        openModal({ type: 'none', state: null })\n      ),\n    }),\n    [modal, openModal]\n  );\n\n  return (\n    <ModalContext.Provider value={value} {...props}>\n      {children}\n    </ModalContext.Provider>\n  );\n}\n\nfunction useModal<T>() {\n  const context = useContext<ModalContextType<T>>(ModalContext);\n  if (context === undefined) {\n    throw new Error('useModal must be used within a ModalProvider');\n  }\n  return context;\n}\n\nexport { ModalProvider, useModal };\n","import {\n  createContext,\n  FC,\n  useMemo,\n  useContext,\n  PropsWithChildren,\n} from 'react';\n\nimport { QueryClient, QueryClientProvider } from 'react-query';\nimport {\n  PendingTransaction,\n  TransactionStateWithResource,\n  TransactionStateWithoutResource,\n  VoterInfo,\n} from '@/types';\nimport { DataActionsBarProvider } from './dataActionsBar';\n\ntype BuildSignSubmitConwayCertTxArgs = {\n  certBuilder?: unknown;\n  voter?: VoterInfo;\n} & (\n  | Pick<TransactionStateWithoutResource, 'type' | 'resourceId'>\n  | Pick<TransactionStateWithResource, 'type' | 'resourceId'>\n);\n\nexport type WalletApi = {\n  dRepID: string;\n  pendingTransaction: PendingTransaction;\n  isEnabled: boolean;\n  stakeKey: string;\n  buildSignSubmitConwayCertTx: ({\n    certBuilder,\n    resourceId,\n    type,\n    voter,\n  }: BuildSignSubmitConwayCertTxArgs) => Promise<string>;\n  // TODO: define types from '@emurgo/cardano-serialization-lib-asmjs'\n  buildDRepRegCert: (url?: string, hash?: string) => Promise<any>;\n  buildVoteDelegationCert: (vote: string) => Promise<any>;\n  buildDRepUpdateCert: (url?: string, hash?: string) => Promise<any>;\n  buildDRepRetirementCert: (voterDeposit: string) => Promise<any>;\n  isPendingTransaction: () => boolean;\n};\n\ntype EpochParams = {\n  drep_deposit: number;\n};\n\ntype PillarContextType = Required<Omit<PillarProviderProps, 'walletApi'>> &\n  WalletApi;\n\nconst PillarContext = createContext<PillarContextType | undefined>(undefined);\n\nexport type PillarProviderProps = {\n  walletApi: WalletApi | null;\n  enable: (name: string) => Promise<{\n    status: string;\n    stakeKey?: boolean;\n    error?: string;\n  }>;\n  isEnableLoading: string | null;\n  apiUrl?: string;\n  validationApiUrl?: string;\n  cExplorerBaseUrl?: string;\n  epochParams: EpochParams;\n  connectWallet: () => void;\n  openFeedbackWindow: () => void;\n  addSuccessAlert: (message: string) => void;\n  addErrorAlert: (message: string) => void;\n  validateMetadata: (url: string, hash: string) => void;\n  generateMetadata: () => void;\n  createJsonLD: (data: unknown) => string;\n  createHash: (json: unknown) => string;\n  routePath?: string;\n  useLocation: () => {\n    pathname: string;\n    search: string;\n    hash: string;\n    state: any;\n    key: any;\n    readonly href: string;\n  };\n  useParams: (routePattern: any) => any;\n  generatePath: (\n    path: string,\n    params?: Record<string, string | number>\n  ) => string;\n  useRouter: () => {\n    push: (href: any) => void;\n    replace: (href: any) => void;\n    prefetch: (href: any) => void;\n    back: () => void;\n    forward: () => void;\n    refresh: () => void;\n  };\n  getAddressFromBech32: (address: string) => any;\n};\n\nexport const PillarProvider: FC<PillarProviderProps & PropsWithChildren> = ({\n  children,\n  apiUrl,\n  walletApi,\n  validationApiUrl,\n  cExplorerBaseUrl,\n  epochParams,\n  connectWallet,\n  openFeedbackWindow,\n  addSuccessAlert,\n  addErrorAlert,\n  validateMetadata,\n  generateMetadata,\n  createJsonLD,\n  createHash,\n  routePath,\n  enable,\n  isEnableLoading,\n  useLocation,\n  useParams,\n  generatePath,\n  useRouter,\n  getAddressFromBech32,\n}) => {\n  const contextValue = useMemo(\n    (): PillarContextType => ({\n      apiUrl: apiUrl ?? import.meta.env.API_URL ?? '',\n      validationApiUrl:\n        validationApiUrl ?? import.meta.env.VALIDATION_API_URL ?? '',\n      epochParams,\n      connectWallet,\n      openFeedbackWindow,\n      addSuccessAlert,\n      addErrorAlert,\n      validateMetadata,\n      generateMetadata,\n      createJsonLD,\n      createHash,\n      enable,\n      isEnableLoading,\n      useLocation,\n      useParams,\n      generatePath,\n      useRouter,\n      ...(walletApi || {\n        dRepID: '',\n        pendingTransaction: {\n          delegate: null,\n          registerAsDrep: null,\n          retireAsDrep: null,\n          registerAsDirectVoter: null,\n          retireAsDirectVoter: null,\n          updateMetaData: null,\n        },\n        isEnabled: false,\n        stakeKey: '',\n        buildSignSubmitConwayCertTx: async () => '',\n        buildDRepRegCert: async () => ({}) as any,\n        buildVoteDelegationCert: async () => ({}) as any,\n        buildDRepUpdateCert: async () => ({}) as any,\n        buildDRepRetirementCert: async () => ({}) as any,\n        isPendingTransaction: () => false,\n      }),\n      cExplorerBaseUrl:\n        cExplorerBaseUrl ?? import.meta.env.C_EXPLORER_BASE_URL ?? '',\n      routePath: routePath ?? '',\n      getAddressFromBech32,\n    }),\n    [\n      apiUrl,\n      validationApiUrl,\n      walletApi,\n      cExplorerBaseUrl,\n      epochParams,\n      connectWallet,\n      openFeedbackWindow,\n      addSuccessAlert,\n      addErrorAlert,\n      validateMetadata,\n      generateMetadata,\n      createJsonLD,\n      createHash,\n      enable,\n      isEnableLoading,\n      useLocation,\n      useParams,\n      generatePath,\n      useRouter,\n    ]\n  );\n\n  return (\n    <PillarContext.Provider value={contextValue}>\n      <QueryClientProvider client={new QueryClient()}>\n        <DataActionsBarProvider>{children}</DataActionsBarProvider>\n      </QueryClientProvider>\n    </PillarContext.Provider>\n  );\n};\n\nexport const usePillarContext = (): PillarContextType => {\n  const context = useContext(PillarContext);\n  if (context === undefined) {\n    throw new Error('usePillarContext must be used within a PillarProvider');\n  }\n  return context;\n};\n","import { Box, Divider } from '@mui/material';\n\nimport { usePillarContext } from '@/context';\nimport { useScreenDimension, useTranslation } from '@/hooks';\nimport { testIdFromLabel } from '@/utils';\n\nimport { Button, Card, Typography } from '@/components';\n\nexport type AutomatedVotingCardProps = {\n  description: string;\n  dataTestId?: string;\n  infoUrl: string;\n  inProgress?: boolean;\n  isSelected?: boolean;\n  onClickDelegate: () => void;\n  title: string;\n  votingPower: string | number;\n  isDelegateLoading?: boolean;\n  transactionId?: string | null;\n};\n\nexport const AutomatedVotingCard = ({\n  dataTestId,\n  description,\n  infoUrl,\n  inProgress,\n  isDelegateLoading,\n  isSelected,\n  onClickDelegate,\n  title,\n  transactionId,\n  votingPower,\n}: AutomatedVotingCardProps) => {\n  const {\n    cExplorerBaseUrl,\n    isEnabled: isConnected,\n    connectWallet,\n  } = usePillarContext();\n  const { isMobile, screenWidth } = useScreenDimension();\n  const { t } = useTranslation();\n  const testIdLabel = testIdFromLabel(title);\n\n  return (\n    <Card\n      {...(inProgress && {\n        variant: 'warning',\n        label: t('inProgress'),\n      })}\n      {...(isSelected && {\n        variant: 'primary',\n      })}\n      sx={{\n        alignItems: 'center',\n        bgcolor: (theme) => `${theme.palette.neutralWhite}40`,\n        boxShadow: (theme) => `0px 4px 15px 0px ${theme.palette.lightBlue}`,\n        display: 'flex',\n        flex: 1,\n        flexDirection: screenWidth < 1024 ? 'column' : 'row',\n        justifyContent: 'space-between',\n        mt: inProgress || isSelected ? 2 : 0,\n        py: 2.25,\n      }}\n      dataTestId={dataTestId ?? `${testIdLabel}-card`}\n    >\n      <Box\n        sx={{\n          flex: 1,\n          mb: screenWidth < 1024 ? 1.5 : 0,\n          width: screenWidth < 1024 ? '100%' : 'auto',\n        }}\n      >\n        <Typography>{title}</Typography>\n        <Typography\n          fontWeight={400}\n          sx={{\n            mt: 0.5,\n            color: screenWidth < 1024 ? 'neutralGray' : 'textBlack',\n            width: screenWidth < 1024 ? 'auto' : '60%',\n          }}\n          variant=\"body2\"\n        >\n          {description}\n        </Typography>\n        {transactionId && (\n          <Button\n            href={`${cExplorerBaseUrl}/tx/${transactionId}`}\n            target=\"_blank\"\n            variant=\"text\"\n            sx={{ width: 'fit-content', p: 0 }}\n          >\n            {t('seeTransaction')}\n          </Button>\n        )}\n      </Box>\n      {!inProgress && !isSelected && (\n        <>\n          <Divider\n            flexItem\n            orientation={screenWidth < 1024 ? 'horizontal' : 'vertical'}\n            sx={{ ml: screenWidth < 1024 ? 0 : 1 }}\n            variant={screenWidth < 1024 ? 'fullWidth' : 'middle'}\n          />\n          <Box\n            sx={{\n              alignContent: 'flex-start',\n              display: 'flex',\n              flexDirection: 'column',\n              px: screenWidth < 1024 ? 0 : 4.25,\n              py: screenWidth < 1024 ? 1 : 0,\n              width: screenWidth < 1024 ? '100%' : 'auto',\n            }}\n          >\n            <Typography color=\"neutralGray\" fontWeight={500} variant=\"caption\">\n              {t('dRepDirectory.votingPower')}\n            </Typography>\n            <Typography sx={{ display: 'flex', flexDirection: 'row', mt: 0.5 }}>\n              {'₳ '}\n              {votingPower}\n            </Typography>\n          </Box>\n          <Divider\n            flexItem\n            orientation={screenWidth < 1024 ? 'horizontal' : 'vertical'}\n            sx={{ mr: screenWidth < 1024 ? 0 : 1 }}\n            variant={screenWidth < 1024 ? 'fullWidth' : 'middle'}\n          />\n          <Box\n            sx={{\n              display: 'flex',\n              flexDirection: 'row',\n              gap: 2.5,\n              mt: screenWidth < 1024 ? 3 : 0,\n              width: screenWidth < 1024 ? '100%' : 'auto',\n            }}\n          >\n            <Button\n              data-testid={`${testIdLabel}-info-button`}\n              href={infoUrl}\n              target=\"_blank\"\n              size={isMobile ? 'medium' : 'large'}\n              variant=\"outlined\"\n              sx={{ flex: screenWidth < 768 ? 1 : undefined }}\n            >\n              {t('info')}\n            </Button>\n            {!isConnected ? (\n              <Button\n                data-testid={`${testIdLabel}-connect-to-delegate-button`}\n                onClick={connectWallet}\n                size={isMobile ? 'medium' : 'large'}\n                sx={{ flex: screenWidth < 768 ? 1 : undefined }}\n              >\n                {t('connectToDelegate')}\n              </Button>\n            ) : (\n              !isSelected && (\n                <Button\n                  data-testid={`${testIdLabel}-delegate-button`}\n                  isLoading={isDelegateLoading}\n                  onClick={onClickDelegate}\n                  size={isMobile ? 'medium' : 'large'}\n                  sx={{ flex: screenWidth < 768 ? 1 : undefined }}\n                  variant=\"contained\"\n                >\n                  {t('delegate')}\n                </Button>\n              )\n            )}\n          </Box>\n        </>\n      )}\n    </Card>\n  );\n};\n","import { useEffect, useState } from 'react';\nimport {\n  Accordion,\n  AccordionDetails,\n  AccordionSummary,\n  Box,\n} from '@mui/material';\n\nimport { DOCS, ICONS } from '@/consts';\nimport { WalletApi } from '@/context';\nimport { useGetNetworkMetrics, useTranslation } from '@/hooks';\nimport { correctAdaFormat } from '@/utils';\nimport {\n  AutomatedVotingOptionCurrentDelegation,\n  AutomatedVotingOptionDelegationId,\n} from '@/types';\nimport { Typography } from '@/components';\nimport { AutomatedVotingCard } from './automatedOptions/AutomatedVotingCard';\n\ntype AutomatedVotingOptionsProps = {\n  currentDelegation?: string | null;\n  delegate: (delegateTo: string) => void;\n  votingPower: string;\n  delegationInProgress?: string;\n  isDelegationLoading?: string | null;\n  pendingTransaction?: WalletApi['pendingTransaction'];\n  txHash?: string | null;\n};\n\nexport const AutomatedVotingOptions = ({\n  currentDelegation,\n  delegate,\n  delegationInProgress,\n  isDelegationLoading,\n  pendingTransaction,\n  votingPower,\n  txHash,\n}: AutomatedVotingOptionsProps) => {\n  const { t } = useTranslation();\n  // TODO: Get network metrics from useAppContext\n  const { networkMetrics, fetchNetworkMetrics } = useGetNetworkMetrics();\n\n  const [isOpen, setIsOpen] = useState<boolean>(false);\n\n  const isDelegatedToAbstain =\n    currentDelegation ===\n    AutomatedVotingOptionCurrentDelegation.drep_always_abstain;\n  const isDelegationToAbstainInProgress =\n    delegationInProgress === AutomatedVotingOptionDelegationId.abstain;\n  const isDelegatedToNoConfidence =\n    currentDelegation ===\n    AutomatedVotingOptionCurrentDelegation.drep_always_no_confidence;\n  const isDelegationToNoConfidenceInProgress =\n    delegationInProgress === AutomatedVotingOptionDelegationId.no_confidence;\n\n  useEffect(() => {\n    fetchNetworkMetrics();\n  }, []);\n\n  useEffect(() => {\n    const shouldBeSetOpen =\n      isDelegatedToAbstain ||\n      isDelegatedToNoConfidence ||\n      isDelegationToAbstainInProgress ||\n      isDelegationToNoConfidenceInProgress;\n\n    setIsOpen(shouldBeSetOpen);\n  }, [\n    isDelegatedToAbstain,\n    isDelegatedToNoConfidence,\n    isDelegationToAbstainInProgress,\n    isDelegationToNoConfidenceInProgress,\n  ]);\n\n  return (\n    <div>\n      <Typography variant=\"title2\" sx={{ mb: 2 }}>\n        {t('dRepDirectory.delegationOptions')}\n      </Typography>\n      <Accordion\n        data-testid=\"automated-voting-options-accordion\"\n        elevation={3}\n        expanded={isOpen}\n        onChange={(_, isExpanded) => setIsOpen(isExpanded)}\n        sx={(theme) => ({\n          bgcolor: `${theme.palette.lightBlue}80`,\n          border: `1px solid ${theme.palette.neutralWhite}`,\n        })}\n      >\n        <AccordionSummary\n          expandIcon={<img alt=\"arrow\" src={ICONS.arrowDownIcon} />}\n          sx={{ borderRadius: 3, px: { xxs: 2, md: 3 } }}\n        >\n          <Typography>{t('dRepDirectory.automatedVotingOptions')}</Typography>\n        </AccordionSummary>\n        <AccordionDetails\n          sx={{ p: { xxs: 2, md: 3 }, pt: { xxs: 0, md: 0 } }}\n          data-testid=\"delegation-options-dropdown\"\n        >\n          <Box\n            sx={{\n              display: 'flex',\n              flexDirection: 'column',\n              gap: 2,\n            }}\n          >\n            <AutomatedVotingCard\n              dataTestId=\"abstain-delegation-card\"\n              description={\n                isDelegatedToAbstain\n                  ? t('dRepDirectory.delegatedToAbstainDescription')\n                  : t('dRepDirectory.abstainCardDefaultDescription')\n              }\n              inProgress={isDelegationToAbstainInProgress}\n              isDelegateLoading={\n                isDelegationLoading ===\n                AutomatedVotingOptionDelegationId.abstain\n              }\n              isSelected={isDelegatedToAbstain}\n              onClickDelegate={() =>\n                delegate(AutomatedVotingOptionDelegationId.abstain)\n              }\n              infoUrl={DOCS.voteAbstain}\n              title={\n                isDelegatedToAbstain\n                  ? t('dRepDirectory.delegatedToAbstainTitle', {\n                      ada: votingPower,\n                    })\n                  : t('dRepDirectory.abstainCardDefaultTitle')\n              }\n              votingPower={\n                networkMetrics\n                  ? correctAdaFormat(networkMetrics?.alwaysAbstainVotingPower)\n                  : ''\n              }\n              transactionId={\n                pendingTransaction?.delegate?.resourceId ===\n                AutomatedVotingOptionDelegationId.abstain\n                  ? pendingTransaction?.delegate?.transactionHash\n                  : isDelegatedToAbstain\n                    ? txHash\n                    : undefined\n              }\n            />\n            <AutomatedVotingCard\n              dataTestId=\"no-confidence-delegation-card\"\n              description={\n                isDelegatedToNoConfidence\n                  ? t('dRepDirectory.delegatedToNoConfidenceDescription')\n                  : t('dRepDirectory.noConfidenceDefaultDescription')\n              }\n              inProgress={isDelegationToNoConfidenceInProgress}\n              isDelegateLoading={\n                isDelegationLoading ===\n                AutomatedVotingOptionDelegationId.no_confidence\n              }\n              isSelected={isDelegatedToNoConfidence}\n              onClickDelegate={() =>\n                delegate(AutomatedVotingOptionDelegationId.no_confidence)\n              }\n              infoUrl={DOCS.voteNoConfidence}\n              title={\n                isDelegatedToNoConfidence\n                  ? t('dRepDirectory.delegatedToNoConfidenceTitle', {\n                      ada: votingPower,\n                    })\n                  : t('dRepDirectory.noConfidenceDefaultTitle')\n              }\n              votingPower={\n                networkMetrics\n                  ? correctAdaFormat(\n                      networkMetrics?.alwaysNoConfidenceVotingPower\n                    )\n                  : ''\n              }\n              transactionId={\n                pendingTransaction?.delegate?.resourceId ===\n                AutomatedVotingOptionDelegationId.no_confidence\n                  ? pendingTransaction?.delegate?.transactionHash\n                  : isDelegatedToNoConfidence\n                    ? txHash\n                    : undefined\n              }\n            />\n          </Box>\n        </AccordionDetails>\n      </Accordion>\n    </div>\n  );\n};\n","import { Avatar, Box, Skeleton, SxProps } from '@mui/material';\n\nimport {\n  getBase64ImageDetails,\n  getMetadataDataMissingStatusTranslation,\n} from '@/utils';\nimport { ICONS } from '@/consts';\nimport { useScreenDimension } from '@/hooks';\nimport { Share, Typography } from '@/components';\nimport { MetadataValidationStatus } from '@/types';\n\ntype DataMissingHeaderProps = {\n  isDataMissing?: MetadataValidationStatus;\n  title?: string;\n  titleStyle?: SxProps;\n  isDRep?: boolean;\n  isValidating?: boolean;\n  image?: string | null;\n  shareLink?: string;\n};\n\nexport const DataMissingHeader = ({\n  title,\n  isDataMissing,\n  titleStyle,\n  isValidating,\n  isDRep,\n  image,\n  shareLink,\n}: DataMissingHeaderProps) => {\n  const base64Image = getBase64ImageDetails(image ?? '');\n  const { screenWidth } = useScreenDimension();\n\n  return (\n    <Box\n      sx={{\n        display: 'grid',\n        gridTemplateColumns: '1fr auto',\n        gap: 2,\n        alignItems: 'center',\n        mb: 2,\n      }}\n      data-testid=\"governance-action-details-card-header\"\n    >\n      <Box\n        sx={{\n          flexDirection: {\n            xxs: 'column',\n            md: 'row',\n          },\n          alignItems: {\n            md: 'center',\n          },\n          display: 'flex',\n        }}\n      >\n        {isDRep &&\n          (isValidating ? (\n            <Skeleton width={80} height={80} variant=\"circular\" />\n          ) : (\n            <Avatar\n              alt=\"drep-image\"\n              src={\n                (base64Image.isValidBase64Image\n                  ? `${base64Image.base64Prefix}${image}`\n                  : image) ?? ICONS.defaultDRepIcon\n              }\n              sx={{ width: 80, height: 80 }}\n              data-testid=\"drep-image\"\n            />\n          ))}\n        {isValidating ? (\n          <Skeleton\n            width=\"120px\"\n            height=\"32px\"\n            sx={{ ...(isDRep && { ml: 4 }) }}\n            variant=\"rounded\"\n          />\n        ) : (\n          <Typography\n            sx={{\n              ...(isDRep && { ml: { md: 3 } }),\n              ...(isDRep && { mt: { xxs: 2, md: 0 } }),\n              textOverflow: 'ellipsis',\n              fontWeight: 600,\n              ...(isDataMissing && { color: 'errorRed' }),\n              ...titleStyle,\n            }}\n            variant=\"title2\"\n            component=\"h1\"\n          >\n            {(isDataMissing &&\n              getMetadataDataMissingStatusTranslation(isDataMissing)) ||\n              title}\n          </Typography>\n        )}\n      </Box>\n      {screenWidth >= 1020 && (\n        <Share link={shareLink ?? window.location.href} />\n      )}\n    </Box>\n  );\n};\n","import { Link } from 'react-router-dom';\nimport { Trans } from 'react-i18next';\nimport { Box, Chip } from '@mui/material';\n\nimport { Button, Share } from '@/components';\nimport { ICONS, PATHS } from '@/consts';\nimport { usePillarContext } from '@/context';\nimport {\n  useGetAdaHolderVotingPowerQuery,\n  useScreenDimension,\n  useTranslation,\n} from '@/hooks';\nimport { correctDRepDirectoryFormat } from '@/utils';\nimport { DRepData, MetadataValidationStatus } from '@/types';\nimport { DataMissingHeader } from './DataMissingHeader';\n\ntype DRepDetailsProps = {\n  dRepData: DRepData;\n  isMe?: boolean;\n  isMyDrep?: boolean;\n  isValidating?: boolean;\n  metadataStatus?: MetadataValidationStatus;\n};\n\nexport const DRepDetailsCardHeader = ({\n  dRepData,\n  isMe,\n  isMyDrep,\n  isValidating,\n  metadataStatus,\n}: DRepDetailsProps) => {\n  const { stakeKey } = usePillarContext();\n  const { t } = useTranslation();\n  const { screenWidth } = useScreenDimension();\n  const { votingPower: myVotingPower } =\n    useGetAdaHolderVotingPowerQuery(stakeKey);\n\n  const { givenName, imageUrl } = dRepData;\n\n  return (\n    <div>\n      {(isMe || isMyDrep) && (\n        <Box\n          sx={{\n            alignSelf: 'stretch',\n            display: 'flex',\n            alignItems: 'center',\n            justifyContent: 'space-between',\n            mb: '18px',\n            ...(screenWidth <= 1020 && {\n              flexDirection: 'column',\n              gap: 3,\n            }),\n          }}\n        >\n          <Chip\n            color=\"primary\"\n            label={\n              <Trans\n                i18nKey={\n                  isMe\n                    ? isMyDrep\n                      ? 'dRepDirectory.myDelegationToYourself'\n                      : 'dRepDirectory.meAsDRep'\n                    : 'dRepDirectory.myDRep'\n                }\n                values={{\n                  ada: correctDRepDirectoryFormat(myVotingPower),\n                }}\n              />\n            }\n            sx={{\n              boxShadow: (theme) => theme.shadows[2],\n              color: (theme) => theme.palette.text.primary,\n              px: 3,\n              py: 0.5,\n              ...(isMyDrep &&\n                !isMe && {\n                  width: '100%',\n                }),\n              ...(screenWidth <= 1020 && {\n                width: '100%',\n              }),\n            }}\n          />\n\n          {isMe && (\n            <Box\n              sx={{\n                alignItems: 'center',\n                display: 'flex',\n                gap: 1,\n                ...(screenWidth < 1020 && {\n                  width: '100%',\n                }),\n              }}\n            >\n              <Link to={`../../${PATHS.editDRepMetadata}`} state={dRepData}>\n                <Button\n                  data-testid=\"edit-drep-data-button\"\n                  variant=\"outlined\"\n                  sx={{\n                    ...(screenWidth < 1020 && {\n                      width: '100%',\n                    }),\n                  }}\n                >\n                  {t('dRepDirectory.editBtn')}\n                  <img\n                    alt=\"sorting active\"\n                    src={ICONS.editIcon}\n                    style={{ marginLeft: '4px' }}\n                  />\n                </Button>\n              </Link>\n              {screenWidth >= 1020 && <Share link={window.location.href} />}\n            </Box>\n          )}\n        </Box>\n      )}\n      <DataMissingHeader\n        isDRep\n        title={givenName ?? undefined}\n        image={imageUrl}\n        isDataMissing={metadataStatus}\n        titleStyle={{ wordBreak: 'break-word', whiteSpace: 'wrap' }}\n        isValidating={isValidating}\n      />\n    </div>\n  );\n};\n","import { PropsWithChildren } from 'react';\nimport { Box, Skeleton } from '@mui/material';\n\nimport { Typography } from '@/components';\n\ntype DrepDetailsInfoItemProps = PropsWithChildren & {\n  label: string;\n  text?: string | null;\n  dataTestId: string;\n  isValidating?: boolean;\n};\n\nexport const DRepDetailsInfoItem = ({\n  children,\n  label,\n  text,\n  dataTestId,\n  isValidating,\n}: DrepDetailsInfoItemProps) => {\n  if (!children && !text) return null;\n  const dataTestIdInfoItemCategoryPrefix = 'info-item';\n  return (\n    <Box\n      sx={{\n        maxWidth: {\n          xxs: '295px',\n          md: '100%',\n        },\n      }}\n    >\n      {isValidating ? (\n        <Skeleton sx={{ mb: 0.5 }} width=\"128px\" height=\"20px\" variant=\"text\" />\n      ) : (\n        <Box\n          sx={{\n            mb: 0.5,\n          }}\n        >\n          <Typography\n            color=\"neutralGray\"\n            fontWeight={600}\n            variant=\"body2\"\n            data-testid={`${dataTestId}-${dataTestIdInfoItemCategoryPrefix}-title`}\n            component=\"h2\"\n          >\n            {label}\n          </Typography>\n        </Box>\n      )}\n      <div\n        data-testid={`${dataTestId}-${dataTestIdInfoItemCategoryPrefix}-description`}\n      >\n        {isValidating ? (\n          <Skeleton\n            variant=\"text\"\n            width=\"100%\"\n            height=\"20px\"\n            sx={{ maxWidth: 608 }}\n          />\n        ) : (\n          <>\n            {text && (\n              <Typography\n                fontWeight={400}\n                sx={{ maxWidth: 608 }}\n                variant=\"body1\"\n              >\n                {text}\n              </Typography>\n            )}\n            {children}\n          </>\n        )}\n      </div>\n    </Box>\n  );\n};\n","import { ButtonBase } from '@mui/material';\n\nimport { Typography } from '@/components';\nimport { ICONS } from '@/consts';\n\nconst ellipsisStyles = {\n  overflow: 'hidden',\n  textOverflow: 'ellipsis',\n  whiteSpace: 'nowrap',\n};\n\ntype CopyableTextProps = {\n  value: string;\n  dataTestId: string;\n  isSemiTransparent?: boolean;\n};\n\nexport const CopyableText = ({\n  value,\n  dataTestId,\n  isSemiTransparent,\n}: CopyableTextProps) => (\n  <ButtonBase\n    onClick={(e) => {\n      navigator.clipboard.writeText(value.toString());\n      e.stopPropagation();\n    }}\n    data-testid={dataTestId}\n    sx={{\n      gap: 1,\n      maxWidth: '100%',\n      '&:hover': {\n        opacity: 0.6,\n        transition: 'opacity 0.3s',\n      },\n    }}\n  >\n    <Typography\n      color=\"primary\"\n      fontWeight={500}\n      sx={{ ...ellipsisStyles, opacity: isSemiTransparent ? 0.75 : 1 }}\n    >\n      {value}\n    </Typography>\n    <img alt=\"\" src={ICONS.copyBlueIcon} />\n  </ButtonBase>\n);\n","import { Box, Link, Skeleton, SxProps } from '@mui/material';\n\nimport { DOCS } from '@/consts';\nimport { useTranslation } from '@/hooks';\nimport { MetadataValidationStatus } from '@/types';\nimport { Typography } from '@/components';\n\nexport const DataMissingInfoBox = ({\n  isDataMissing,\n  isInProgress,\n  isValidating,\n  isSubmitted,\n  isDrep = false,\n  sx,\n}: {\n  isDataMissing?: MetadataValidationStatus;\n  isInProgress?: boolean;\n  isValidating?: boolean;\n  isSubmitted?: boolean;\n  isDrep?: boolean;\n  sx?: SxProps;\n}) => {\n  const { t } = useTranslation();\n\n  const gaMetadataErrorMessage = {\n    [MetadataValidationStatus.URL_NOT_FOUND]: isDrep\n      ? t('errors.dRep.message.dataMissing')\n      : t('errors.gAMetadata.message.dataMissing'),\n    [MetadataValidationStatus.INVALID_JSONLD]: isDrep\n      ? t('errors.dRep.message.incorrectFormat')\n      : t('errors.gAMetadata.message.incorrectFormat'),\n    [MetadataValidationStatus.INVALID_HASH]: isDrep\n      ? t('errors.dRep.message.notVerifiable')\n      : t('errors.gAMetadata.message.notVerifiable'),\n    [MetadataValidationStatus.INCORRECT_FORMAT]: isDrep\n      ? t('errors.dRep.message.incorrectFormat')\n      : t('errors.gAMetadata.message.incorrectFormat'),\n  }[isDataMissing as MetadataValidationStatus];\n\n  const gaMetadataErrorDescription = {\n    [MetadataValidationStatus.URL_NOT_FOUND]: isDrep\n      ? t('errors.dRep.description.dataMissing')\n      : t('errors.gAMetadata.description.dataMissing'),\n    [MetadataValidationStatus.INVALID_JSONLD]: isDrep\n      ? t('errors.dRep.description.incorrectFormat')\n      : t('errors.gAMetadata.description.incorrectFormat'),\n    [MetadataValidationStatus.INVALID_HASH]: isDrep\n      ? t('errors.dRep.description.notVerifiable')\n      : t('errors.gAMetadata.description.notVerifiable'),\n    [MetadataValidationStatus.INCORRECT_FORMAT]: isDrep\n      ? t('errors.dRep.description.incorrectFormat')\n      : t('errors.gAMetadata.description.incorrectFormat'),\n  }[isDataMissing as MetadataValidationStatus];\n\n  return isDataMissing && !isSubmitted && !isInProgress ? (\n    <Box\n      sx={{\n        mb: 4,\n        pr: 6,\n        ...sx,\n      }}\n    >\n      {isValidating ? (\n        <Skeleton\n          sx={{ mb: 0.5 }}\n          width=\"128px\"\n          height=\"48px\"\n          variant=\"rounded\"\n        />\n      ) : (\n        <Typography\n          sx={{\n            fontSize: '18px',\n            fontWeight: 500,\n            color: 'errorRed',\n            mb: 0.5,\n          }}\n        >\n          {gaMetadataErrorMessage}\n        </Typography>\n      )}\n      {isValidating ? (\n        <Skeleton\n          sx={{ mb: 0.5 }}\n          width=\"100%\"\n          height=\"96px\"\n          variant=\"rounded\"\n        />\n      ) : (\n        <Typography\n          sx={{\n            fontWeight: 400,\n            color: 'errorRed',\n            mb: 0.5,\n          }}\n        >\n          {gaMetadataErrorDescription}\n        </Typography>\n      )}\n      {isValidating ? (\n        <Skeleton width=\"128px\" height=\"24px\" variant=\"text\" />\n      ) : (\n        <Link\n          href={DOCS.dRepErrors}\n          target=\"_blank\"\n          sx={{\n            fontFamily: 'Poppins',\n            fontSize: '16px',\n            lineHeight: '24px',\n            cursor: 'pointer',\n          }}\n        >\n          {t('learnMore')}\n        </Link>\n      )}\n    </Box>\n  ) : null;\n};\n","import { Chip, ChipProps, styled } from '@mui/material';\n\nimport { cyan, errorRed, successGreen, voltaireTheme } from '@/theme';\nimport { DRepStatus } from '@/types';\n\ninterface StatusPillProps {\n  status: DRepStatus;\n  dataTestId?: string;\n  label?: string;\n  size?: 'small' | 'medium';\n  sx?: ChipProps['sx'];\n}\n\nexport const StatusPill = ({\n  dataTestId,\n  status,\n  label = status,\n  size = 'small',\n  sx,\n}: StatusPillProps) => (\n  <StyledChip\n    data-testid={dataTestId ?? `${status}-pill`}\n    status={status}\n    size={size}\n    label={label}\n    sx={{\n      px: status === DRepStatus.Yourself ? 0.75 : 0.5,\n      py: 0.5,\n      height: 24,\n      ...sx,\n    }}\n  />\n);\n\nconst bgColor = {\n  [DRepStatus.Active]: successGreen.c200,\n  [DRepStatus.Inactive]: errorRed.c100,\n  [DRepStatus.Retired]: cyan.c100,\n  [DRepStatus.Yourself]: voltaireTheme.palette.lightBlue,\n};\n\nconst textColor = {\n  [DRepStatus.Active]: successGreen.c700,\n  [DRepStatus.Inactive]: errorRed.c500,\n  [DRepStatus.Retired]: cyan.c500,\n  [DRepStatus.Yourself]: voltaireTheme.palette.textBlack,\n};\n\nconst StyledChip = styled(Chip)<{ status: DRepStatus }>(\n  ({ theme: themeStyles, status }) => ({\n    backgroundColor: bgColor[status],\n    color: textColor[status],\n    fontSize: '0.75rem',\n    textTransform: 'capitalize',\n    ...(status !== DRepStatus.Yourself && {\n      border: `2px solid ${themeStyles.palette.neutralWhite}`,\n    }),\n  })\n);\n","import { useMutation } from 'react-query';\n\nimport { postValidate } from '@/services';\nimport { MUTATION_KEYS } from '@/consts';\nimport { MetadataValidationDTO } from '@/types';\nimport { usePillarContext } from '@/context';\n\nexport const useValidateMutation = <MetadataType>() => {\n  const { validationApiUrl } = usePillarContext();\n  const { data, isLoading, mutateAsync } = useMutation({\n    mutationFn: (body: MetadataValidationDTO) =>\n      postValidate<MetadataType>(validationApiUrl, body),\n    mutationKey: [MUTATION_KEYS.postValidateKey],\n  });\n\n  return {\n    validateMetadata: mutateAsync,\n    validationStatus: data,\n    isValidating: isLoading,\n  };\n};\n","import { Box, Link } from '@mui/material';\nimport { useEffect, useState } from 'react';\n\nimport { usePillarContext } from '@/context';\nimport { useDelegateTodRep, useScreenDimension, useTranslation } from '@/hooks';\nimport { DRepData, MetadataValidationStatus } from '@/types';\nimport { Button, Card, ExternalModalButton, Typography } from '@/components';\n\nimport { DRepDetailsCardHeader } from './details/DRepDetailsCardHeader';\nimport { DRepDetailsInfoItem } from './details/DRepDetailsInfoItem';\nimport { CopyableText } from './details/CopyableText';\nimport { DataMissingInfoBox } from './details/DataMissingInfoBox';\nimport { StatusPill } from './common/StatusPill';\nimport { useValidateMutation } from '@/hooks/mutations';\nimport { ICONS } from '@/consts';\nimport {\n  correctDRepDirectoryFormat,\n  encodeCIP129Identifier,\n} from '../../utils';\n\ntype DRepDetailsProps = {\n  dRepData: DRepData;\n  isMe?: boolean;\n  isMyDrep?: boolean;\n  isMyDrepInProgress?: boolean;\n};\n\nexport const DRepDetailsCard = ({\n  dRepData,\n  isMe,\n  isMyDrep,\n  isMyDrepInProgress,\n}: DRepDetailsProps) => {\n  const {\n    pendingTransaction,\n    isEnabled: isConnected,\n    connectWallet,\n  } = usePillarContext();\n  const { t } = useTranslation();\n  const { screenWidth } = useScreenDimension();\n  const { delegate, isDelegating } = useDelegateTodRep();\n\n  const {\n    motivations,\n    objectives,\n    paymentAddress,\n    qualifications,\n    status,\n    url,\n    view,\n    drepId,\n    votingPower,\n    metadataHash,\n  } = dRepData;\n\n  const [isValidating, setIsValidating] = useState(false);\n  const [metadataStatus, setMetadataStatus] = useState<\n    MetadataValidationStatus | undefined\n  >();\n  const { validateMetadata } = useValidateMutation();\n\n  useEffect(() => {\n    if (!url) return;\n\n    const validate = async () => {\n      setIsValidating(true);\n\n      const { status: metadataValidationStatus } = await validateMetadata({\n        standard: 'CIP119',\n        url,\n        hash: metadataHash ?? '',\n      });\n\n      setMetadataStatus(metadataValidationStatus);\n      setIsValidating(false);\n    };\n    validate();\n  }, [url]);\n\n  return (\n    <Card\n      {...((isMe || isMyDrep) && {\n        variant: 'primary',\n      })}\n      {...(isMyDrepInProgress && {\n        variant: 'warning',\n        label: t('inProgress'),\n      })}\n      sx={{\n        borderRadius: 5,\n        pb: 4.25,\n        pt: 2.25,\n        display: 'flex',\n        flexDirection: 'column',\n        gap: 6,\n      }}\n    >\n      {/* BASIC INFO */}\n      <Box\n        sx={{\n          display: 'flex',\n          flexDirection: 'column',\n          gap: 2,\n        }}\n      >\n        <DRepDetailsCardHeader\n          dRepData={dRepData}\n          isMe={isMe}\n          isMyDrep={isMyDrep}\n          isValidating={isValidating}\n          metadataStatus={metadataStatus}\n        />\n        {/* ERROR MESSAGES */}\n        {metadataStatus && (\n          <DataMissingInfoBox\n            isDataMissing={metadataStatus}\n            isDrep\n            sx={{ mb: 0 }}\n            isValidating={isValidating}\n          />\n        )}\n        {metadataStatus && !!url && (\n          <ExternalModalButton\n            label={t('govActions.seeExternalData')}\n            sx={{ mb: 0, alignSelf: 'flex-start' }}\n            url={url}\n          />\n        )}\n        {/* ERROR MESSAGES END */}\n        <DRepDetailsInfoItem\n          label={t('drepId')}\n          dataTestId=\"cip-129-drep-id\"\n          isValidating={isValidating}\n        >\n          <CopyableText\n            value={encodeCIP129Identifier({\n              txID: `${'22'}${drepId}`,\n              bech32Prefix: 'drep',\n            })}\n            dataTestId=\"copy-cip-129-drep-id-button\"\n          />\n        </DRepDetailsInfoItem>\n\n        <DRepDetailsInfoItem\n          label={t('cip105DRepId')}\n          dataTestId=\"cip-105-drep-id\"\n          isValidating={isValidating}\n        >\n          <CopyableText\n            isSemiTransparent\n            value={view}\n            dataTestId=\"copy-drep-id-button\"\n          />\n        </DRepDetailsInfoItem>\n\n        <DRepDetailsInfoItem\n          label={t('status')}\n          dataTestId=\"drep-status\"\n          isValidating={isValidating}\n        >\n          <StatusPill status={status} />\n        </DRepDetailsInfoItem>\n        <DRepDetailsInfoItem\n          label={t('votingPower')}\n          dataTestId=\"drep-voting-power\"\n          isValidating={isValidating}\n        >\n          <Typography\n            data-testid=\"voting-power\"\n            sx={{ display: 'flex', flexDirection: 'row', mt: 0.5 }}\n          >\n            {'₳ '}\n            {correctDRepDirectoryFormat(votingPower)}\n          </Typography>\n        </DRepDetailsInfoItem>\n      </Box>\n      {/* BASIC INFO END */}\n\n      {/* BUTTONS */}\n      {!isValidating &&\n        isConnected &&\n        ['Active', 'Inactive'].includes(status) &&\n        !isMyDrep && (\n          <Button\n            data-testid=\"delegate-button\"\n            disabled={!!pendingTransaction?.delegate}\n            isLoading={\n              isDelegating === dRepData.view || isDelegating === dRepData.drepId\n            }\n            onClick={() => delegate(dRepData.drepId)}\n            size=\"extraLarge\"\n            sx={{ width: '100%', maxWidth: screenWidth < 1024 ? '100%' : 286 }}\n            variant=\"contained\"\n          >\n            {t('delegate')}\n          </Button>\n        )}\n      {!isValidating &&\n        !isConnected &&\n        ['Active', 'Inactive'].includes(status) && (\n          <Button\n            data-testid=\"connect-to-delegate-button\"\n            onClick={connectWallet}\n            size=\"extraLarge\"\n            sx={{ width: '100%', maxWidth: screenWidth < 1024 ? '100%' : 286 }}\n            variant=\"outlined\"\n          >\n            {t('connectToDelegate')}\n          </Button>\n        )}\n      {/* BUTTONS END */}\n\n      {/* CIP-119 DATA */}\n      {!metadataStatus && (\n        <>\n          <DRepDetailsInfoItem\n            label={t('forms.dRepData.objectives')}\n            text={objectives}\n            dataTestId=\"objectives\"\n          />\n          <DRepDetailsInfoItem\n            label={t('forms.dRepData.motivations')}\n            text={motivations}\n            dataTestId=\"motivations\"\n          />\n          <DRepDetailsInfoItem\n            label={t('forms.dRepData.qualifications')}\n            text={qualifications}\n            dataTestId=\"qualifications\"\n          />\n          <DRepDetailsInfoItem\n            label={t('forms.dRepData.paymentAddress')}\n            dataTestId=\"payment-address\"\n          >\n            {paymentAddress && (\n              <CopyableText\n                value={paymentAddress}\n                dataTestId=\"copy-payment-address-button\"\n              />\n            )}\n          </DRepDetailsInfoItem>\n          {url && (\n            <DRepDetailsInfoItem\n              label={t('forms.dRepData.metadataUrl')}\n              dataTestId=\"metadata-url\"\n            >\n              <Link\n                data-testid=\"metadata-url-link\"\n                href={url}\n                target=\"_blank\"\n                sx={{\n                  overflow: 'hidden',\n                  textOverflow: 'ellipsis',\n                  display: 'flex',\n                  gap: 1,\n                  alignItems: 'center',\n                }}\n              >\n                <Typography\n                  color=\"primary\"\n                  fontWeight={400}\n                  sx={{\n                    overflow: 'hidden',\n                    textOverflow: 'ellipsis',\n                  }}\n                >\n                  {url}\n                </Typography>\n                <img\n                  alt=\"link\"\n                  height={16}\n                  src={ICONS.externalLinkIcon}\n                  width={16}\n                />\n              </Link>\n            </DRepDetailsInfoItem>\n          )}\n          {metadataHash && (\n            <DRepDetailsInfoItem\n              label={t('forms.dRepData.metadataHash')}\n              dataTestId=\"metadata-hash\"\n            >\n              <CopyableText\n                value={metadataHash}\n                dataTestId=\"copy-metadata-hash\"\n              />\n            </DRepDetailsInfoItem>\n          )}\n        </>\n      )}\n      {/* CIP-119 DATA END */}\n    </Card>\n  );\n};\n","\"use client\";\n\nimport createSvgIcon from \"./utils/createSvgIcon.js\";\nimport { jsx as _jsx } from \"react/jsx-runtime\";\nexport default createSvgIcon(/*#__PURE__*/_jsx(\"path\", {\n  d: \"M15.5 14h-.79l-.28-.27C15.41 12.59 16 11.11 16 9.5 16 5.91 13.09 3 9.5 3S3 5.91 3 9.5 5.91 16 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14\"\n}), 'Search');","import { Dispatch, SetStateAction, useCallback, useRef } from 'react';\nimport {\n  Box,\n  Checkbox,\n  FormControlLabel,\n  FormLabel,\n  Typography,\n} from '@mui/material';\n\nimport { useOnClickOutside, useScreenDimension } from '@/hooks';\n\ninterface Props {\n  chosenFilters: string[];\n  setChosenFilters: Dispatch<SetStateAction<string[]>>;\n  closeFilters: () => void;\n  options: {\n    key: string;\n    label: string;\n  }[];\n  title?: string;\n}\n\nexport const DataActionsFilters = ({\n  chosenFilters,\n  setChosenFilters,\n  closeFilters,\n  options,\n  title,\n}: Props) => {\n  const handleFilterChange = useCallback(\n    (e: React.ChangeEvent<HTMLInputElement>) => {\n      // TODO: Refine if it is needed to remove this eslint-disable\n      // eslint-disable-next-line @typescript-eslint/no-unused-expressions, no-unused-expressions, no-sequences\n      e.target.name, e.target.checked;\n      let filters = [...chosenFilters];\n      if (e.target.checked) {\n        filters.push(e.target.name);\n      } else {\n        filters = filters.filter((str) => str !== e.target.name);\n      }\n      setChosenFilters(filters);\n    },\n    [chosenFilters, setChosenFilters]\n  );\n\n  const { isMobile, screenWidth } = useScreenDimension();\n\n  const wrapperRef = useRef<HTMLDivElement>(null);\n  useOnClickOutside(wrapperRef, closeFilters);\n\n  return (\n    <Box\n      display=\"flex\"\n      flexDirection=\"column\"\n      position=\"absolute\"\n      sx={{\n        background: '#FBFBFF',\n        boxShadow: '1px 2px 11px 0px #00123D5E',\n        borderRadius: '10px',\n        padding: '12px 0px',\n        width: screenWidth < 850 ? '315px' : '415px',\n        zIndex: '1',\n        right: isMobile ? '59px' : '115px',\n        top: '53px',\n      }}\n      ref={wrapperRef}\n    >\n      {title && (\n        <FormLabel\n          sx={{\n            fontSize: 14,\n            fontWeight: 500,\n            color: '#9792B5',\n            paddingX: '20px',\n          }}\n        >\n          {title}\n        </FormLabel>\n      )}\n      {options.map((item) => (\n        <Box\n          key={item.key}\n          paddingX=\"20px\"\n          sx={[{ '&:hover': { bgcolor: '#E6EBF7' } }]}\n          bgcolor={\n            chosenFilters?.includes(item.key) ? '#FFF0E7' : 'transparent'\n          }\n        >\n          <FormControlLabel\n            control={\n              <Checkbox\n                inputProps={{\n                  // eslint-disable-next-line @typescript-eslint/ban-ts-comment\n                  // @ts-expect-error\n                  'data-testid': `${item.label.replace(/ /g, '')}-checkbox`,\n                }}\n                onChange={handleFilterChange}\n                name={item.key}\n                checked={chosenFilters?.includes(item.key)}\n              />\n            }\n            label={\n              <Typography fontSize={14} fontWeight={500}>\n                {item.label}\n              </Typography>\n            }\n          />\n        </Box>\n      ))}\n    </Box>\n  );\n};\n","import { Dispatch, SetStateAction, useRef } from 'react';\nimport {\n  Box,\n  FormControl,\n  FormControlLabel,\n  Radio,\n  RadioGroup,\n  Typography,\n} from '@mui/material';\n\nimport { useTranslation, useOnClickOutside } from '@/hooks';\n\ninterface Props {\n  chosenSorting: string;\n  setChosenSorting: Dispatch<SetStateAction<string>>;\n  closeSorts: () => void;\n  options: {\n    key: string;\n    label: string;\n  }[];\n}\n\nexport const DataActionsSorting = ({\n  chosenSorting,\n  setChosenSorting,\n  closeSorts,\n  options,\n}: Props) => {\n  const { t } = useTranslation();\n\n  const wrapperRef = useRef<HTMLDivElement>(null);\n  useOnClickOutside(wrapperRef, closeSorts);\n\n  return (\n    <Box\n      display=\"flex\"\n      flexDirection=\"column\"\n      position=\"absolute\"\n      sx={{\n        background: '#FBFBFF',\n        boxShadow: '1px 2px 11px 0px #00123D5E',\n        borderRadius: '10px',\n        padding: '12px 0px',\n        width: '315px',\n        zIndex: '1',\n        right: '3px',\n        top: '53px',\n      }}\n      ref={wrapperRef}\n    >\n      <FormControl>\n        <Box display=\"flex\" justifyContent=\"space-between\" px=\"20px\">\n          <Typography sx={{ fontSize: 14, fontWeight: 500, color: '#9792B5' }}>\n            {t('sortBy')}\n          </Typography>\n          <Box sx={{ cursor: 'pointer' }} onClick={() => setChosenSorting('')}>\n            <Typography fontSize={14} fontWeight={500} color=\"primary\">\n              {t('clear')}\n            </Typography>\n          </Box>\n        </Box>\n        <RadioGroup\n          aria-labelledby=\"demo-controlled-radio-buttons-group\"\n          name=\"controlled-radio-buttons-group\"\n          value={chosenSorting}\n          onChange={(e) => {\n            setChosenSorting(e.target.value);\n          }}\n        >\n          {options.map((item) => (\n            <FormControlLabel\n              sx={[\n                {\n                  margin: 0,\n                  px: '20px',\n                  bgcolor:\n                    chosenSorting === item.key ? '#FFF0E7' : 'transparent',\n                },\n                { '&:hover': { bgcolor: '#E6EBF7' } },\n              ]}\n              key={item.key}\n              value={item.key}\n              control={\n                // TODO: Fix typing of inputProps\n                // eslint-disable-next-line @typescript-eslint/ban-ts-comment\n                // @ts-expect-error\n                <Radio inputProps={{ 'data-testid': `${item.key}-radio` }} />\n              }\n              label={item.label}\n            />\n          ))}\n        </RadioGroup>\n      </FormControl>\n    </Box>\n  );\n};\n","import { Dispatch, SetStateAction } from 'react';\nimport { Box } from '@mui/material';\n\nimport { useScreenDimension, useTranslation } from '@/hooks';\nimport { Typography } from '@/components';\nimport { ICONS } from '@/consts';\nimport { voltaireTheme as theme } from '../../../theme';\n\ntype Props = {\n  filtersOpen?: boolean;\n  setFiltersOpen?: Dispatch<SetStateAction<boolean>>;\n  chosenFiltersLength?: number;\n  chosenSorting: string;\n  sortOpen: boolean;\n  setSortOpen: Dispatch<SetStateAction<boolean>>;\n  children?: React.ReactNode;\n  isFiltering?: boolean;\n};\n\nexport const OrderActionsChip = (props: Props) => {\n  const { t } = useTranslation();\n  const { isMobile } = useScreenDimension();\n\n  const {\n    palette: { secondary },\n  } = theme;\n\n  const {\n    filtersOpen,\n    setFiltersOpen = () => {},\n    chosenFiltersLength = 0,\n    chosenSorting,\n    sortOpen,\n    setSortOpen,\n    isFiltering = true,\n    children,\n  } = props;\n\n  return (\n    <Box\n      display=\"flex\"\n      width=\"min-content\"\n      alignItems=\"center\"\n      ml=\"8px\"\n      gap={isMobile ? '8px' : '24px'}\n      position=\"relative\"\n      sx={{ alignSelf: 'end' }}\n    >\n      {isFiltering && (\n        <Box\n          sx={{\n            position: 'relative',\n            display: 'flex',\n            alignItems: 'center',\n            justifyContent: 'center',\n            cursor: 'pointer',\n            ...(!isMobile && {\n              background: filtersOpen ? secondary.main : 'transparent',\n              borderRadius: '99px',\n              padding: '12px 14px',\n            }),\n          }}\n          onClick={() => {\n            setSortOpen(false);\n            if (isFiltering) {\n              setFiltersOpen(!filtersOpen);\n            }\n          }}\n          data-testid=\"filters-button\"\n        >\n          <img\n            alt=\"filter\"\n            src={filtersOpen ? ICONS.filterWhiteIcon : ICONS.filterIcon}\n            style={{\n              borderRadius: '100%',\n              marginRight: '8px',\n              overflow: 'visible',\n              height: 20,\n              width: 20,\n              objectFit: 'contain',\n              ...(isMobile && {\n                background: filtersOpen ? secondary.main : 'transparent',\n                padding: '14px',\n                marginRight: '0',\n              }),\n            }}\n          />\n          {!isMobile && (\n            <Typography\n              variant=\"body1\"\n              sx={{\n                color: filtersOpen ? 'white' : 'primaryBlue',\n                fontWeight: 500,\n              }}\n            >\n              {t('filter')}\n            </Typography>\n          )}\n          {!filtersOpen && chosenFiltersLength > 0 && (\n            <Box\n              sx={{\n                alignItems: 'center',\n                background: secondary.main,\n                borderRadius: '100%',\n                color: 'white',\n                display: 'flex',\n                fontSize: '12px',\n                height: '16px',\n                justifyContent: 'center',\n                position: 'absolute',\n                right: '-3px',\n                top: '0',\n                width: '16px',\n              }}\n            >\n              <Typography variant=\"caption\" color=\"#FFFFFF\">\n                {chosenFiltersLength}\n              </Typography>\n            </Box>\n          )}\n        </Box>\n      )}\n      <Box\n        sx={{\n          position: 'relative',\n          display: 'flex',\n          alignItems: 'center',\n          justifyContent: 'center',\n          cursor: 'pointer',\n          ...(!isMobile && {\n            background: sortOpen ? secondary.main : 'transparent',\n            borderRadius: '99px',\n            padding: '12px 14px',\n          }),\n        }}\n        onClick={() => {\n          if (isFiltering) {\n            setFiltersOpen(false);\n          }\n          setSortOpen(!sortOpen);\n        }}\n        data-testid=\"sort-button\"\n      >\n        <img\n          alt=\"sort\"\n          src={sortOpen ? ICONS.sortWhiteIcon : ICONS.sortIcon}\n          style={{\n            borderRadius: '100%',\n            marginRight: '8px',\n            height: 20,\n            width: 20,\n            objectFit: 'contain',\n            ...(isMobile && {\n              background: sortOpen ? secondary.main : 'transparent',\n              padding: '14px',\n              marginRight: '0',\n            }),\n          }}\n        />\n        {!isMobile && (\n          <Typography\n            variant=\"body1\"\n            sx={{\n              color: sortOpen ? 'white' : 'primaryBlue',\n              fontWeight: 500,\n              whiteSpace: 'nowrap',\n            }}\n          >\n            {chosenSorting ? `${t('sortBy')}: ${chosenSorting}` : t('sort')}\n          </Typography>\n        )}\n      </Box>\n      {children}\n    </Box>\n  );\n};\n","import { Dispatch, FC, SetStateAction } from 'react';\nimport { Box, InputBase } from '@mui/material';\nimport Search from '@mui/icons-material/Search';\n\nimport { voltaireTheme as theme } from '../../../theme';\nimport { DataActionsFilters } from './DataActionsFilters';\nimport { DataActionsSorting } from './DataActionsSorting';\nimport { OrderActionsChip } from './OrderActionsChip';\n\ntype DataActionsBarProps = {\n  chosenFilters?: string[];\n  chosenFiltersLength?: number;\n  chosenSorting: string;\n  closeFilters?: () => void;\n  closeSorts: () => void;\n  filterOptions?: {\n    key: string;\n    label: string;\n  }[];\n  filtersOpen?: boolean;\n  filtersTitle?: string;\n  isFiltering?: boolean;\n  searchText: string;\n  setChosenFilters?: Dispatch<SetStateAction<string[]>>;\n  setChosenSorting: Dispatch<SetStateAction<string>>;\n  setFiltersOpen?: Dispatch<SetStateAction<boolean>>;\n  setSearchText: Dispatch<SetStateAction<string>>;\n  setSortOpen: Dispatch<SetStateAction<boolean>>;\n  sortOpen: boolean;\n  sortOptions?: {\n    key: string;\n    label: string;\n  }[];\n};\n\nexport const DataActionsBar: FC<DataActionsBarProps> = ({ ...props }) => {\n  const {\n    chosenFilters = [],\n    chosenFiltersLength,\n    chosenSorting,\n    closeFilters = () => {},\n    closeSorts,\n    filterOptions = [],\n    filtersOpen,\n    filtersTitle,\n    isFiltering = true,\n    searchText,\n    setChosenFilters = () => {},\n    setChosenSorting,\n    setFiltersOpen,\n    setSearchText,\n    setSortOpen,\n    sortOpen,\n    sortOptions = [],\n  } = props;\n  const {\n    palette: { boxShadow2 },\n  } = theme;\n\n  return (\n    <>\n      <Box alignItems=\"center\" display=\"flex\" justifyContent=\"space-between\">\n        <InputBase\n          inputProps={{ 'data-testid': 'search-input' }}\n          onChange={(e) => setSearchText(e.target.value)}\n          placeholder=\"Search...\"\n          value={searchText}\n          startAdornment={\n            <Search\n              style={{\n                color: '#99ADDE',\n                height: 16,\n                marginRight: 4,\n                width: 16,\n              }}\n            />\n          }\n          sx={{\n            bgcolor: 'white',\n            border: 1,\n            borderColor: 'secondaryBlue',\n            borderRadius: 50,\n            boxShadow: `2px 2px 20px 0px ${boxShadow2}`,\n            fontSize: 11,\n            fontWeight: 500,\n            height: 48,\n            padding: '16px 24px',\n            maxWidth: 500,\n          }}\n        />\n        <OrderActionsChip\n          chosenFiltersLength={chosenFiltersLength}\n          filtersOpen={filtersOpen}\n          isFiltering={isFiltering}\n          setFiltersOpen={setFiltersOpen}\n          chosenSorting={chosenSorting}\n          setSortOpen={setSortOpen}\n          sortOpen={sortOpen}\n        >\n          {filtersOpen && (\n            <DataActionsFilters\n              chosenFilters={chosenFilters}\n              setChosenFilters={setChosenFilters}\n              closeFilters={closeFilters}\n              options={filterOptions}\n              title={filtersTitle}\n            />\n          )}\n          {sortOpen && (\n            <DataActionsSorting\n              chosenSorting={chosenSorting}\n              setChosenSorting={setChosenSorting}\n              closeSorts={closeSorts}\n              options={sortOptions}\n            />\n          )}\n        </OrderActionsChip>\n      </Box>\n    </>\n  );\n};\n","import { bech32 } from 'bech32';\nimport { Buffer } from 'buffer';\n\n// Ensure Buffer is polyfilled for browser environments\nif (typeof window !== 'undefined' && typeof window.Buffer === 'undefined') {\n  window.Buffer = Buffer;\n}\n\n/**\n * Encodes a CIP129 identifier based on the provided transaction ID, index, and bech32 prefix.\n * @param txID - The transaction ID.\n * @param index - The index.\n * @param bech32Prefix - The bech32 prefix.\n * @returns The generated CIP129 identifier.\n */\nexport const encodeCIP129Identifier = ({\n  txID,\n  index,\n  bech32Prefix,\n}: {\n  txID: string;\n  index?: string;\n  bech32Prefix: string;\n}) => {\n  const govActionBytes = Buffer.from(index ? txID + index : txID, 'hex');\n  const words = bech32.toWords(govActionBytes);\n  return bech32.encode(bech32Prefix, words);\n};\n\n/**\n * Decodes a CIP129 identifier.\n * @param cip129Identifier - The CIP129 identifier to decode.\n * @returns An object containing the decoded transaction ID, index, and prefix.\n */\nexport const decodeCIP129Identifier = (cip129Identifier: string) => {\n  const { prefix, words } = bech32.decode(cip129Identifier);\n  const buffer = Buffer.from(bech32.fromWords(words));\n  const txID = buffer.subarray(0, 32).toString('hex');\n  const index = buffer.subarray(32).toString('hex');\n  return { txID, index, prefix };\n};\n","import Box from '@mui/material/Box';\nimport ButtonBase from '@mui/material/ButtonBase';\nimport Divider from '@mui/material/Divider';\nimport Avatar from '@mui/material/Avatar';\nimport Skeleton from '@mui/material/Skeleton';\n\nimport { Button, Card, Typography } from '@/components';\nimport { useTranslation } from '@/hooks';\nimport { DRepData, DRepStatus } from '@/types';\nimport { usePillarContext } from '@/context';\nimport { ICONS, PATHS } from '@/consts';\nimport { encodeCIP129Identifier } from '@/utils/cip129identifier';\nimport { getBase64ImageDetails } from '@/utils/getBase64ImageDetails';\nimport {\n  correctDRepDirectoryFormat,\n  ellipsizeText,\n  getMetadataDataMissingStatusTranslation,\n} from '@/utils';\nimport { StatusPill } from '../common/StatusPill';\n\ntype DRepCardProps = {\n  dRep: DRepData;\n  isConnected: boolean;\n  isDelegationLoading?: boolean;\n  isInProgress?: boolean;\n  isMe?: boolean;\n  isMyDrep?: boolean;\n  onDelegate?: () => void;\n};\n\nexport const DRepCard = ({\n  dRep: { status, type, view, votingPower, givenName, imageUrl, drepId },\n  isConnected,\n  isDelegationLoading,\n  isInProgress,\n  isMe,\n  isMyDrep,\n  onDelegate,\n}: DRepCardProps) => {\n  const { t } = useTranslation();\n  const { addSuccessAlert, useRouter } = usePillarContext();\n  const router = useRouter();\n\n  // const { openModal } = useModal();\n\n  // const openChooseWalletModal = () => {\n  //   openModal({\n  //     type: 'chooseWallet',\n  //     state: {\n  //       pathToNavigate: PATHS.dashboardDRepDirectoryDRep.replace(\n  //         ':dRepId',\n  //         view\n  //       ),\n  //     },\n  //   });\n  // };\n\n  const metadataStatus = undefined;\n\n  const cip129Identifier = encodeCIP129Identifier({\n    txID: `${false ? '23' : '22'}${drepId}`,\n    bech32Prefix: 'drep',\n  });\n\n  const base64Image = getBase64ImageDetails(imageUrl ?? '');\n\n  return (\n    <Card\n      {...(isMe && {\n        variant: 'primary',\n      })}\n      {...(false && {\n        variant: 'error',\n      })}\n      {...(isInProgress && {\n        variant: 'warning',\n        label: t('inProgress'),\n      })}\n      dataTestId={`${view}-${\n        onDelegate\n          ? 'drep'\n          : isInProgress\n            ? 'delegation-in-progress'\n            : 'delegated'\n      }-card`}\n      sx={{ container: 'root / inline-size', py: 2.5 }}\n    >\n      {isMe && (\n        <StatusPill\n          status={DRepStatus.Yourself}\n          sx={{ mb: 1.5, display: { lg: 'none' } }}\n        />\n      )}\n      <Box\n        display=\"flex\"\n        flexDirection=\"column\"\n        rowGap={4}\n        columnGap={6}\n        sx={{\n          '@container root (min-width: 480px)': {\n            flexDirection: 'row',\n          },\n        }}\n      >\n        <Box flex={2} minWidth={0} sx={{ containerType: 'inline-size' }}>\n          <Box\n            display=\"flex\"\n            flexDirection=\"column\"\n            rowGap={3}\n            columnGap={10}\n            sx={{\n              '@container (min-width: 480px)': {\n                flexDirection: 'row',\n                alignItems: 'center',\n              },\n              containerType: 'inline-size',\n            }}\n          >\n            <Box flexDirection=\"row\" minWidth={0} display=\"flex\">\n              {false ? (\n                <Skeleton variant=\"circular\" width={40} height={40} />\n              ) : (\n                <Avatar\n                  alt=\"drep-image\"\n                  src={\n                    (base64Image.isValidBase64Image\n                      ? `${base64Image.base64Prefix}${imageUrl}`\n                      : imageUrl) ?? ICONS.defaultDRepIcon\n                  }\n                  data-testid=\"drep-image\"\n                />\n              )}\n              <Box\n                sx={{\n                  marginLeft: {\n                    xxs: 1,\n                    xs: 2,\n                    sm: 3,\n                  },\n                }}\n              >\n                <Typography\n                  sx={{ ellipsisStyles, color: metadataStatus && 'errorRed' }}\n                >\n                  {metadataStatus\n                    ? getMetadataDataMissingStatusTranslation(metadataStatus)\n                    : ellipsizeText(givenName ?? '', 25)}\n                </Typography>\n                <Box\n                  sx={{\n                    display: 'flex',\n                    flexDirection: 'column',\n                  }}\n                >\n                  <ButtonBase\n                    data-testid={`${cip129Identifier}-copy-id-button`}\n                    onClick={(e) => {\n                      navigator.clipboard.writeText(cip129Identifier);\n                      addSuccessAlert(t('alerts.copiedToClipboard'));\n                      e.stopPropagation();\n                    }}\n                    sx={{\n                      gap: 1,\n                      width: '250px',\n                      maxWidth: {\n                        xxs: '200px',\n                        xs: '100%',\n                      },\n                      '&:hover': {\n                        opacity: 0.6,\n                        transition: 'opacity 0.3s',\n                      },\n                      display: 'flex',\n                      flexDirection: 'row',\n                    }}\n                  >\n                    <Typography\n                      color=\"primary\"\n                      variant=\"body2\"\n                      sx={ellipsisStyles}\n                    >\n                      {cip129Identifier}\n                    </Typography>\n                    <img alt=\"\" src={ICONS.copyBlueIcon} />\n                  </ButtonBase>\n                  <ButtonBase\n                    data-testid={`${view}-copy-id-button`}\n                    onClick={(e) => {\n                      navigator.clipboard.writeText(view);\n                      addSuccessAlert(t('alerts.copiedToClipboard'));\n                      e.stopPropagation();\n                    }}\n                    sx={{\n                      gap: 1,\n                      width: '250px',\n                      maxWidth: {\n                        xxs: '200px',\n                        xs: '100%',\n                      },\n                      '&:hover': {\n                        opacity: 0.6,\n                        transition: 'opacity 0.3s',\n                      },\n                    }}\n                  >\n                    <Typography variant=\"body2\" sx={ellipsisStyles}>\n                      (CIP-105){' '}\n                      <Typography\n                        color=\"primary\"\n                        variant=\"body2\"\n                        component=\"span\"\n                      >\n                        {view}\n                      </Typography>\n                    </Typography>\n                    <img alt=\"\" src={ICONS.copyBlueIcon} />\n                  </ButtonBase>\n                </Box>\n              </Box>\n            </Box>\n\n            <Box\n              sx={{\n                display: 'flex',\n                flex: { xl: 1 },\n                gap: 3,\n              }}\n            >\n              <Box\n                sx={{\n                  width: { lg: '128px' },\n                  display: 'flex',\n                  alignItems: 'flex-end',\n                  flexDirection: 'column',\n                }}\n              >\n                <Typography\n                  data-testid={`${view}-voting-power-label`}\n                  variant=\"caption\"\n                  color=\"textSecondary\"\n                  sx={{ mb: 0.5 }}\n                >\n                  {t('votingPower')}\n                </Typography>\n                <Typography\n                  data-testid={`${view}-voting-power`}\n                  sx={{ whiteSpace: 'nowrap' }}\n                >\n                  ₳ {correctDRepDirectoryFormat(votingPower)}\n                </Typography>\n              </Box>\n              <Divider\n                orientation=\"vertical\"\n                flexItem\n                sx={({ palette }) => ({ borderColor: palette.lightBlue })}\n              />\n              <Box>\n                <Typography\n                  data-testid={`${view}-status-label`}\n                  variant=\"caption\"\n                  color=\"textSecondary\"\n                  sx={{ mb: 0.5 }}\n                >\n                  {t('status')}\n                </Typography>\n                <Box display=\"flex\" flexDirection=\"row\">\n                  <StatusPill\n                    dataTestId={`${view}-${status}-pill`}\n                    status={status}\n                  />\n                  {isMe && (\n                    <StatusPill\n                      dataTestId={`${view}-yourself-pill`}\n                      status={DRepStatus.Yourself}\n                      sx={{ ml: 0.75, display: { lg: 'flex', xxs: 'none' } }}\n                    />\n                  )}\n                </Box>\n              </Box>\n            </Box>\n          </Box>\n        </Box>\n\n        <Box\n          display=\"flex\"\n          gap={2.5}\n          sx={{\n            '@container root (min-width: 480px)': {\n              justifyContent: 'flex-end',\n              alignItems: 'center',\n            },\n            minWidth: {\n              xxs: '233px',\n              xs: isConnected ? '233px' : '310px',\n            },\n          }}\n        >\n          {type === 'DRep' && (\n            <Button\n              data-testid={`${view}-view-details-button`}\n              variant=\"outlined\"\n              onClick={() =>\n                router.push(\n                  (isConnected\n                    ? PATHS.dashboardDRepDirectoryDRep\n                    : PATHS.dRepDirectoryDRep\n                  ).replace(':dRepId', view)\n                )\n              }\n            >\n              {t('viewDetails')}\n            </Button>\n          )}\n          {['Active', 'Inactive'].includes(status) &&\n            isConnected &&\n            onDelegate &&\n            !isMyDrep &&\n            !isInProgress && (\n              <Button\n                data-testid={`${view}-delegate-button`}\n                onClick={console.log}\n                isLoading={isDelegationLoading}\n              >\n                {t('delegate')}\n              </Button>\n            )}\n          {['Active', 'Inactive'].includes(status) && !isConnected && (\n            <Button\n              data-testid={`${view}-connect-to-delegate-button`}\n              onClick={console.log}\n            >\n              {t('connectToDelegate')}\n            </Button>\n          )}\n        </Box>\n      </Box>\n    </Card>\n  );\n};\n\nconst ellipsisStyles = {\n  overflow: 'hidden',\n  textOverflow: 'ellipsis',\n  whiteSpace: 'nowrap',\n  maxWidth: { xxs: '200px', xs: '100%' },\n} as const;\n","import { useTranslation } from '@/hooks';\n\nimport { Card, Typography } from '@/components';\n\nexport const EmptyStateDrepDirectory = () => {\n  const { t } = useTranslation();\n\n  return (\n    <Card\n      border\n      elevation={0}\n      sx={{\n        alignItems: 'center',\n        display: 'flex',\n        flexDirection: 'column',\n        gap: 1,\n        py: 5,\n        width: '-webkit-fill-available',\n      }}\n    >\n      <Typography fontSize={22}>\n        {t('dRepDirectory.noResultsForTheSearchTitle')}\n      </Typography>\n      <Typography fontWeight={400}>\n        {t('dRepDirectory.noResultsForTheSearchDescription')}\n      </Typography>\n    </Card>\n  );\n};\n","import { FC, useEffect } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { Box } from '@mui/material';\n\nimport { Button, CircularLoader, Typography } from '@/components';\nimport { DREP_DIRECTORY_FILTERS, DREP_DIRECTORY_SORTING } from '@/consts';\nimport { usePillarContext, useDataActionsBar } from '@/context';\nimport {\n  useDelegateTodRep,\n  useGetAdaHolderCurrentDelegationQuery,\n  useGetDRepDetailsQuery,\n  useGetDRepListInfiniteQuery,\n} from '@/hooks';\nimport { isSameDRep } from '@/utils';\nimport { DRepListSort, DRepStatus } from '@/types';\nimport { DataActionsBar } from './list/DataActionsBar';\nimport { DRepCard } from './list/DRepCard';\nimport { EmptyStateDrepDirectory } from './EmptyStateDrepDirectory';\n\nexport const DRepList: FC = () => {\n  const {\n    dRepID: myDRepId,\n    pendingTransaction,\n    stakeKey,\n    isEnabled: isConnected,\n  } = usePillarContext();\n  const { t } = useTranslation();\n\n  const { debouncedSearchText, ...dataActionsBarProps } = useDataActionsBar();\n  const { chosenFilters, chosenSorting, setChosenSorting } =\n    dataActionsBarProps;\n\n  useEffect(() => {\n    if (!chosenSorting) setChosenSorting(DRepListSort.Random);\n  }, [chosenSorting, setChosenSorting]);\n\n  const { delegate, isDelegating } = useDelegateTodRep();\n\n  const { currentDelegation } = useGetAdaHolderCurrentDelegationQuery(stakeKey);\n  const inProgressDelegation = pendingTransaction.delegate?.resourceId;\n\n  const { dRep: meAsDRep } = useGetDRepDetailsQuery(myDRepId, {\n    enabled: !!inProgressDelegation || !!currentDelegation,\n  });\n\n  const {\n    dRepData: dRepList,\n    isPreviousData,\n    dRepListHasNextPage,\n    dRepListFetchNextPage,\n  } = useGetDRepListInfiniteQuery(\n    {\n      searchPhrase: debouncedSearchText,\n      sorting: chosenSorting as DRepListSort,\n      status: chosenFilters as DRepStatus[],\n    },\n    {\n      enabled: !!chosenSorting,\n      keepPreviousData: true,\n    }\n  );\n\n  if (!dRepList) {\n    return <CircularLoader />;\n  }\n\n  const showMeAsDRep =\n    debouncedSearchText === myDRepId || debouncedSearchText === '';\n  const listedDRepsWithoutYourself = dRepList?.filter(\n    (dRep) => !dRep.doNotList && !isSameDRep(dRep, myDRepId)\n  );\n  const dRepListToDisplay =\n    meAsDRep && showMeAsDRep\n      ? [meAsDRep, ...listedDRepsWithoutYourself]\n      : listedDRepsWithoutYourself;\n\n  return (\n    <>\n      <Typography fontSize={18} fontWeight={500} sx={{ mb: 3 }}>\n        {t('dRepDirectory.listTitle')}\n      </Typography>\n\n      <DataActionsBar\n        {...dataActionsBarProps}\n        filterOptions={DREP_DIRECTORY_FILTERS}\n        filtersTitle={t('dRepDirectory.filterTitle')}\n        sortOptions={DREP_DIRECTORY_SORTING}\n      />\n\n      <Box\n        component=\"ul\"\n        display=\"flex\"\n        flexDirection=\"column\"\n        gap={3}\n        mt={4}\n        p={0}\n        sx={{\n          opacity: isPreviousData ? 0.5 : 1,\n          transition: 'opacity 0.2s',\n          flex: 1,\n        }}\n      >\n        {dRepList?.length === 0 && <EmptyStateDrepDirectory />}\n        {dRepListToDisplay?.map((dRep) => (\n          <Box key={dRep.drepId} component=\"li\" sx={{ listStyle: 'none' }}>\n            <DRepCard\n              dRep={dRep}\n              isConnected={isConnected}\n              isDelegationLoading={\n                isDelegating === dRep.view || isDelegating === dRep.drepId\n              }\n              isMe={isSameDRep(dRep, myDRepId)}\n              isMyDrep={isSameDRep(dRep, currentDelegation?.dRepView)}\n              onDelegate={() => delegate(dRep.drepId)}\n            />\n          </Box>\n        ))}\n      </Box>\n\n      {dRepListHasNextPage && dRepList.length >= 10 && (\n        <Box sx={{ justifyContent: 'center', display: 'flex' }}>\n          <Button\n            data-testid=\"show-more-button\"\n            variant=\"outlined\"\n            onClick={() => dRepListFetchNextPage()}\n          >\n            {t('showMore')}\n          </Button>\n        </Box>\n      )}\n    </>\n  );\n};\n","import { FC } from 'react';\nimport { Trans } from 'react-i18next';\n\nimport { usePillarContext } from '@/context';\nimport { useGetAdaHolderVotingPowerQuery } from '@/hooks';\nimport { correctAdaFormat, isSameDRep } from '@/utils';\nimport { DRepData } from '@/types';\nimport { Typography } from '@/components';\nimport { DRepCard } from './list/DRepCard';\n\ninterface Props {\n  dRep: DRepData | null | undefined;\n  inProgress?: boolean;\n}\n\nexport const MyDelegation: FC<Props> = ({ dRep, inProgress }) => {\n  const {\n    dRepID: myDRepId,\n    pendingTransaction,\n    stakeKey,\n    isEnabled: isConnected,\n  } = usePillarContext();\n\n  const inProgressDelegation = pendingTransaction.delegate?.resourceId;\n\n  const { votingPower } = useGetAdaHolderVotingPowerQuery(stakeKey);\n  const ada = correctAdaFormat(votingPower);\n\n  if (!dRep) return null;\n\n  if (inProgress)\n    return (\n      <DRepCard\n        dRep={dRep}\n        isConnected={isConnected}\n        isMe={isSameDRep(dRep, myDRepId)}\n        isInProgress\n      />\n    );\n\n  return (\n    <div>\n      <Typography variant=\"title2\" sx={{ mb: 2 }}>\n        <Trans i18nKey=\"dRepDirectory.myDelegation\" values={{ ada }} />\n      </Typography>\n      <DRepCard\n        dRep={dRep}\n        isConnected={isConnected}\n        isInProgress={isSameDRep(dRep, inProgressDelegation)}\n        isMe={isSameDRep(dRep, myDRepId)}\n      />\n    </div>\n  );\n};\n","import { SxProps } from '@mui/material';\nimport { Typography } from '../../../../components';\n\nexport type InfoTextProps = {\n  label: string;\n  sx?: SxProps;\n};\n\nexport const InfoText = ({ label, sx }: InfoTextProps) => (\n  <Typography color=\"#FF833B\" sx={sx} variant=\"body1\">\n    {label.toLocaleUpperCase()}\n  </Typography>\n);\n","import { Typography } from '../../../../components';\n\ntype FieldDescriptionProps = {\n  title: string;\n  subtitle: string;\n};\n\nexport const FieldDescription = ({\n  title,\n  subtitle,\n}: FieldDescriptionProps) => (\n  <div>\n    <Typography variant=\"body1\" sx={{ mb: 0.5 }}>\n      {title}\n    </Typography>\n    <Typography variant=\"body2\" fontWeight={400} sx={{ mb: 1.5 }}>\n      {subtitle}\n    </Typography>\n  </div>\n);\n","\"use client\";\n\nimport createSvgIcon from \"./utils/createSvgIcon.js\";\nimport { jsx as _jsx } from \"react/jsx-runtime\";\nexport default createSvgIcon(/*#__PURE__*/_jsx(\"path\", {\n  d: \"M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6zM8 9h8v10H8zm7.5-5-1-1h-5l-1 1H5v2h14V4z\"\n}), 'DeleteOutline');","import { Fragment, useCallback } from 'react';\nimport {\n  Control,\n  FieldErrors,\n  UseFormRegister,\n  useFieldArray,\n} from 'react-hook-form';\nimport { Box } from '@mui/material';\nimport DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';\n\nimport { useRules, useTranslation } from '@/hooks';\nimport { DRepDataFormValues } from '@/types';\nimport { FieldDescription } from './FieldDescription';\nimport { Button, ControlledField } from '../../../../components';\n\nconst MAX_NUMBER_OF_LINKS = 7;\n\ntype ReferencesSectionProps = {\n  type: 'link' | 'identity';\n  control: Control<DRepDataFormValues>;\n  errors: FieldErrors<DRepDataFormValues>;\n  register: UseFormRegister<DRepDataFormValues>;\n};\n\nexport const ReferencesSection = ({\n  type,\n  control,\n  errors,\n  register,\n}: ReferencesSectionProps) => {\n  const { fieldName, jsonldType } = (() => {\n    // eslint-disable-next-line default-case\n    switch (type) {\n      case 'link':\n        return {\n          fieldName: 'linkReferences',\n          jsonldType: 'Link',\n        } as const;\n      case 'identity':\n        return {\n          fieldName: 'identityReferences',\n          jsonldType: 'Identity',\n        } as const;\n    }\n  })();\n\n  const { t } = useTranslation();\n\n  const {\n    append,\n    fields: references,\n    remove,\n  } = useFieldArray({\n    control,\n    name: fieldName,\n  });\n\n  const addLink = useCallback(\n    () => append(getEmptyReference(jsonldType)),\n    [append]\n  );\n\n  const removeLink = useCallback((index: number) => remove(index), [remove]);\n\n  const Rules = useRules();\n  return (\n    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>\n      <FieldDescription\n        title={t(`forms.dRepData.referenceTypes.${type}.title`)}\n        subtitle={t(`forms.dRepData.referenceTypes.${type}.description`)}\n      />\n      {references.map((field, index) => (\n        <Fragment key={field.id}>\n          <ControlledField.Input\n            {...{ control, errors }}\n            {...register(`${fieldName}.${index}.label`)}\n            errors={errors}\n            label={t('forms.dRepData.referenceDescription')}\n            name={`${fieldName}.${index}.label`}\n            helpfulText={t('forms.dRepData.referenceDescriptionHelpfulText')}\n            dataTestId={`${type}-reference-description-${index + 1}-input`}\n            errorDataTestId={`${type}-reference-description-${index + 1}-error`}\n            helpfulTextDataTestId={`${type}-reference-description-${\n              index + 1\n            }-hint`}\n            rules={Rules.LINK_DESCRIPTION}\n          />\n          <ControlledField.Input\n            {...{ control, errors }}\n            {...register(`${fieldName}.${index}.uri`)}\n            errors={errors}\n            endAdornment={\n              references.length > 1 ? (\n                <DeleteOutlineIcon\n                  color=\"primary\"\n                  data-testid={`delete-link-${index + 1}-button`}\n                  sx={{ cursor: 'pointer', height: 24, with: 24 }}\n                  onClick={() => removeLink(index)}\n                />\n              ) : null\n            }\n            label={t('forms.dRepData.referenceURL')}\n            layoutStyles={{ mb: 3 }}\n            name={`${fieldName}.${index}.uri`}\n            dataTestId={`${type}-reference-url-${index + 1}-input`}\n            errorDataTestId={`${type}-reference-url-${index + 1}-error`}\n            helpfulTextDataTestId={`${type}-reference-url-${index + 1}-hint`}\n            rules={Rules.LINK_URL}\n          />\n        </Fragment>\n      ))}\n      {references?.length < MAX_NUMBER_OF_LINKS ? (\n        <Button\n          data-testid={`add-${type}-reference-button`}\n          onClick={addLink}\n          size=\"extraLarge\"\n          variant=\"text\"\n        >\n          {t('addLink')}\n        </Button>\n      ) : null}\n    </Box>\n  );\n};\n\nconst getEmptyReference = (type: 'Link' | 'Identity') => ({\n  '@type': type,\n  uri: '',\n  label: '',\n});\n","import { Control, FieldErrors, UseFormRegister } from 'react-hook-form';\nimport { Box } from '@mui/material';\n\nimport { ControlledField, Spacer, Typography } from '@/components';\nimport { useRules, useScreenDimension, useTranslation } from '@/hooks';\nimport { DRepDataFormValues } from '@/types';\nimport { InfoText } from './dRepDataForm/InfoText';\nimport { FieldDescription } from './dRepDataForm/FieldDescription';\nimport { ReferencesSection } from './dRepDataForm/ReferencesSection';\n\ntype Props = {\n  control: Control<DRepDataFormValues>;\n  errors: FieldErrors<DRepDataFormValues>;\n  register: UseFormRegister<DRepDataFormValues>;\n};\n\nexport const DRepDataForm = ({ control, errors, register }: Props) => {\n  const { t } = useTranslation();\n  const { isMobile } = useScreenDimension();\n  const Rules = useRules();\n\n  return (\n    <div>\n      <Box textAlign=\"center\">\n        <InfoText label={t('dRepData.required')} />\n        <Typography sx={{ mt: 0.5, mb: isMobile ? 3 : 4 }} variant=\"headline4\">\n          {t('dRepData.dRepName')}\n        </Typography>\n        <Typography fontWeight={400} sx={{ mb: 4 }} variant=\"body1\">\n          {t('dRepData.dRepNameDescription')}\n        </Typography>\n      </Box>\n      <ControlledField.Input\n        {...{ control, errors }}\n        dataTestId=\"name-input\"\n        label={t('forms.dRepData.givenName')}\n        name=\"givenName\"\n        helpfulText={t('forms.dRepData.givenNameHelpfulText')}\n        rules={Rules.GIVEN_NAME}\n      />\n      <Spacer y={isMobile ? 5 : 6} />\n      <Box textAlign=\"center\">\n        <InfoText label={t('dRepData.optional')} />\n        <Typography sx={{ mt: 0.5, mb: isMobile ? 3 : 4 }} variant=\"headline4\">\n          {t('dRepData.aboutYou')}\n        </Typography>\n      </Box>\n      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 5 }}>\n        <div>\n          <FieldDescription\n            title={t('forms.dRepData.objectives')}\n            subtitle={t('forms.dRepData.objectivesHelpfulText')}\n          />\n          <ControlledField.TextArea\n            {...{ control, errors }}\n            data-testid=\"objectives-input\"\n            label={t('forms.dRepData.objectives')}\n            hideLabel\n            name=\"objectives\"\n            rules={Rules.OBJECTIVES}\n            maxLength={Rules.OBJECTIVES.maxLength.value}\n          />\n        </div>\n        <div>\n          <FieldDescription\n            title={t('forms.dRepData.motivations')}\n            subtitle={t('forms.dRepData.motivationsHelpfulText')}\n          />\n          <ControlledField.TextArea\n            {...{ control, errors }}\n            data-testid=\"motivations-input\"\n            label={t('forms.dRepData.motivations')}\n            hideLabel\n            name=\"motivations\"\n            rules={Rules.MOTIVATIONS}\n            maxLength={Rules.MOTIVATIONS.maxLength.value}\n          />\n        </div>\n        <div>\n          <FieldDescription\n            title={t('forms.dRepData.qualifications')}\n            subtitle={t('forms.dRepData.qualificationsHelpfulText')}\n          />\n          <ControlledField.TextArea\n            {...{ control, errors }}\n            data-testid=\"qualifications-input\"\n            label={t('forms.dRepData.qualifications')}\n            hideLabel\n            name=\"qualifications\"\n            rules={Rules.QUALIFICATIONS}\n            maxLength={Rules.QUALIFICATIONS.maxLength.value}\n          />\n        </div>\n        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 4, mt: 3 }}>\n          <Typography\n            variant=\"title2\"\n            fontWeight={600}\n            sx={{ textAlign: 'center' }}\n          >\n            {t('forms.dRepData.references')}\n          </Typography>\n          <ReferencesSection\n            type=\"link\"\n            control={control}\n            errors={errors}\n            register={register}\n          />\n          <ReferencesSection\n            type=\"identity\"\n            control={control}\n            errors={errors}\n            register={register}\n          />\n        </Box>\n        <div>\n          <Typography\n            variant=\"title2\"\n            fontWeight={600}\n            sx={{ textAlign: 'center', mb: 1.5 }}\n          >\n            {t('forms.dRepData.paymentAddress')}\n          </Typography>\n          <Typography\n            variant=\"body2\"\n            fontWeight={400}\n            sx={{ textAlign: 'center', mb: 0 }}\n          >\n            {t('forms.dRepData.paymentAddressHelpfulText')}\n          </Typography>\n        </div>\n        <ControlledField.Input\n          {...{ control, errors }}\n          label={t('forms.dRepData.paymentAddress')}\n          name=\"paymentAddress\"\n          rules={Rules.PAYMENT_ADDRESS}\n        />\n        <ControlledField.Checkbox\n          {...{ control, errors }}\n          label={t('forms.dRepData.doNotList')}\n          labelStyles={{ fontSize: 16, fontWeight: 500 }}\n          helpfulText={t('forms.dRepData.doNotListHelpfulText')}\n          layoutStyles={{ ml: -1.5 }}\n          name=\"doNotList\"\n          size=\"large\"\n        />\n      </Box>\n    </div>\n  );\n};\n","import { useNavigate } from 'react-router-dom';\nimport { Box } from '@mui/material';\n\nimport { PATHS } from '@/consts';\nimport { useScreenDimension, useTranslation } from '@/hooks';\nimport { Button } from '@/components';\n\ninterface Props {\n  actionButtonText?: string;\n  actionButtonDataTestId?: string;\n  onActionButton: () => void;\n  isLoadingActionButton?: boolean;\n  disableActionButton?: boolean;\n  backButtonText?: string;\n  onBackButton?: () => void;\n}\n\nexport const TransactionStepButtons = ({\n  actionButtonText,\n  actionButtonDataTestId,\n  backButtonText,\n  isLoadingActionButton,\n  disableActionButton,\n  onBackButton,\n  onActionButton,\n}: Props) => {\n  const { isMobile } = useScreenDimension();\n  const navigate = useNavigate();\n  const { t } = useTranslation();\n\n  const navigateToDashboard = () => navigate(PATHS.dashboard);\n\n  return (\n    <Box\n      sx={{\n        display: 'flex',\n        flexDirection: isMobile ? 'column-reverse' : 'row',\n        gap: isMobile ? 3 : 0,\n        justifyContent: 'space-between',\n      }}\n    >\n      <Button\n        data-testid=\"back-button\"\n        onClick={onBackButton ?? navigateToDashboard}\n        size=\"extraLarge\"\n        sx={{\n          px: 6,\n        }}\n        variant=\"outlined\"\n      >\n        {backButtonText ?? t('back')}\n      </Button>\n      <Button\n        data-testid={actionButtonDataTestId ?? 'continue-button'}\n        disabled={disableActionButton || isLoadingActionButton}\n        isLoading={isLoadingActionButton}\n        onClick={onActionButton}\n        size=\"extraLarge\"\n        sx={{\n          px: 6,\n        }}\n        variant=\"contained\"\n      >\n        {actionButtonText ?? t('continue')}\n      </Button>\n    </Box>\n  );\n};\n","import { Dispatch, SetStateAction, useEffect } from 'react';\nimport { useLocation } from 'react-router-dom';\nimport { Box } from '@mui/material';\n\nimport { usePillarContext } from '@/context';\nimport {\n  useDRepDataForm,\n  useGetDRepDetailsQuery,\n  useTranslation,\n} from '@/hooks';\nimport { DRepData, Reference } from '@/types';\nimport { DRepDataForm } from '../common/DRepDataForm';\nimport { TransactionStepButtons } from '../common/TransactionStepButtons';\n\nexport const EditDRepForm = ({\n  onClickCancel,\n  setStep,\n  loadUserData,\n  setLoadUserData,\n}: {\n  onClickCancel: () => void;\n  setStep: Dispatch<SetStateAction<number>>;\n  loadUserData: boolean;\n  setLoadUserData: Dispatch<SetStateAction<boolean>>;\n}) => {\n  const { state } = useLocation();\n  const { t } = useTranslation();\n  const { dRepID } = usePillarContext();\n  const { control, errors, isError, register, watch, reset } = useDRepDataForm({\n    type: 'edit',\n  });\n  const { dRep: yourselfDRep } = useGetDRepDetailsQuery(dRepID, {\n    enabled: !state,\n  });\n\n  const onClickContinue = () => {\n    setStep(2);\n    setLoadUserData(false);\n  };\n\n  const isContinueButtonDisabled = !watch('givenName') || isError;\n\n  useEffect(() => {\n    if (loadUserData) {\n      const data: DRepData = state ?? yourselfDRep;\n      const groupedReferences = data?.references?.reduce<\n        Record<string, Reference[]>\n      >((acc, reference) => {\n        const type = reference['@type'];\n        if (!acc[type]) {\n          acc[type] = [];\n        }\n        acc[type].push(reference);\n        return acc;\n      }, {});\n      reset({\n        ...data,\n        objectives: data?.objectives ?? '',\n        motivations: data?.motivations ?? '',\n        qualifications: data?.qualifications ?? '',\n        paymentAddress: data?.paymentAddress ?? '',\n        linkReferences: groupedReferences?.Link ?? [getEmptyReference('Link')],\n        identityReferences: groupedReferences?.Identity ?? [\n          getEmptyReference('Identity'),\n        ],\n      });\n    }\n  }, [yourselfDRep, loadUserData]);\n\n  return (\n    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 8 }}>\n      <DRepDataForm control={control} errors={errors} register={register} />\n      <TransactionStepButtons\n        onActionButton={onClickContinue}\n        disableActionButton={isContinueButtonDisabled}\n        onBackButton={onClickCancel}\n        backButtonText={t('cancel')}\n      />\n    </Box>\n  );\n};\n\nconst getEmptyReference = (type: 'Link' | 'Identity') => ({\n  '@type': type,\n  uri: '',\n  label: '',\n});\n","import { Dispatch, SetStateAction } from 'react';\nimport { Box, Link } from '@mui/material';\n\nimport { DOCS } from '@/consts';\nimport { useScreenDimension, useTranslation, useDRepDataForm } from '@/hooks';\nimport { ControlledField, Spacer, Typography } from '@/components';\nimport { TransactionStepButtons } from '../common/TransactionStepButtons';\n\nexport const EditDRepStoreDataInfo = ({\n  setStep,\n}: {\n  setStep: Dispatch<SetStateAction<number>>;\n}) => {\n  const { t } = useTranslation();\n  const { isMobile } = useScreenDimension();\n  const { control, errors, watch } = useDRepDataForm({ type: 'edit' });\n\n  const onClickBackButton = () => setStep(1);\n\n  const onClickContinue = () => setStep(3);\n\n  const isContinueDisabled = !watch('storeData');\n\n  return (\n    <>\n      <Typography sx={{ textAlign: 'center' }} variant=\"headline4\">\n        {t('editMetadata.storeDataTitle')}\n      </Typography>\n      <Link\n        href={DOCS.storingMetadata}\n        target=\"_blank\"\n        sx={{\n          cursor: 'pointer',\n          fontSize: 16,\n          fontWeight: 500,\n          fontFamily: 'Poppins',\n          my: 4,\n          textAlign: 'center',\n          textDecoration: 'none',\n        }}\n      >\n        {t('editMetadata.storeDataLink')}\n      </Link>\n      <ControlledField.Checkbox\n        {...{ control, errors }}\n        name=\"storeData\"\n        label={t('editMetadata.storeDataCheckboxLabel')}\n      />\n      <Spacer y={isMobile ? 4 : 12.5} />\n      <Box display=\"flex\" flex={1} />\n      <TransactionStepButtons\n        onActionButton={onClickContinue}\n        actionButtonText={t('register')}\n        actionButtonDataTestId=\"register-button\"\n        disableActionButton={isContinueDisabled}\n        onBackButton={onClickBackButton}\n      />\n    </>\n  );\n};\n","\"use client\";\n\nimport createSvgIcon from \"./utils/createSvgIcon.js\";\nimport { jsx as _jsx } from \"react/jsx-runtime\";\nexport default createSvgIcon(/*#__PURE__*/_jsx(\"path\", {\n  d: \"M19 19H5V5h7V3H5c-1.11 0-2 .9-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2v-7h-2zM14 3v2h3.59l-9.83 9.83 1.41 1.41L19 6.41V10h2V3z\"\n}), 'OpenInNew');","import { Box, SxProps } from '@mui/material';\n\nimport { Typography } from '@/components';\nimport { voltaireTheme as theme } from '@/theme';\n\nexport type StepProps = {\n  label: string;\n  stepNumber: number | string;\n  component?: React.ReactNode;\n  componentsLayoutStyles?: SxProps;\n  layoutStyles?: SxProps;\n};\nexport const Step = ({\n  component,\n  componentsLayoutStyles,\n  label,\n  layoutStyles,\n  stepNumber,\n}: StepProps) => {\n  const {\n    palette: { boxShadow2 },\n  } = theme;\n\n  return (\n    <Box\n      sx={{\n        flexDirection: 'row',\n        display: 'flex',\n        width: '100%',\n        ...layoutStyles,\n      }}\n    >\n      <Box\n        sx={{\n          alignItems: 'center',\n          borderRadius: '100%',\n          boxShadow: `2px 2px 20px 0px ${boxShadow2}`,\n          display: 'flex',\n          height: 54,\n          justifyContent: 'center',\n          width: 54,\n        }}\n      >\n        <Typography color=\"primary\" fontWeight={400} variant=\"title2\">\n          {stepNumber}\n        </Typography>\n      </Box>\n\n      <Box\n        sx={{\n          display: 'flex',\n          flex: 1,\n          flexDirection: 'column',\n          ml: 3,\n          ...componentsLayoutStyles,\n        }}\n      >\n        <Typography fontWeight={500} variant=\"body1\">\n          {label}\n        </Typography>\n        {component}\n      </Box>\n    </Box>\n  );\n};\n","import { Dispatch, SetStateAction, useEffect } from 'react';\nimport { Box } from '@mui/material';\nimport OpenInNewIcon from '@mui/icons-material/OpenInNew';\n\nimport { DOCS, ICONS } from '@/consts';\nimport { Button, ControlledField, Spacer, Typography } from '@/components';\nimport {\n  useTranslation,\n  useScreenDimension,\n  useDRepDataForm,\n  useRules,\n} from '@/hooks';\nimport { ellipsizeText } from '@/utils';\nimport { Step } from '../common/Step';\nimport { TransactionStepButtons } from '../common/TransactionStepButtons';\n\ntype StorageInformationProps = {\n  setStep: Dispatch<SetStateAction<number>>;\n};\n\nexport const EditDRepStorageInformation = ({\n  setStep,\n}: StorageInformationProps) => {\n  const { t } = useTranslation();\n  const Rules = useRules();\n  const {\n    control,\n    errors,\n    generateMetadata,\n    getValues,\n    isSubmitting,\n    onClickDownloadJson,\n    onSubmit,\n    watch,\n  } = useDRepDataForm({ type: 'edit', onCancel: () => setStep(1) });\n  const { screenWidth } = useScreenDimension();\n\n  const fileName = getValues('givenName').replace(/\\s/g, '');\n\n  const isActionButtonDisabled = !watch('storingURL') || !!errors.storingURL;\n\n  const onClickBack = () => setStep(2);\n\n  useEffect(() => {\n    generateMetadata();\n  }, []);\n\n  return (\n    <>\n      <Typography sx={{ textAlign: 'center' }} variant=\"headline4\">\n        {t('editMetadata.storingInformationTitle')}\n      </Typography>\n      <Button\n        endIcon={\n          <OpenInNewIcon\n            sx={{\n              color: 'primary',\n              height: 17,\n              width: 17,\n            }}\n          />\n        }\n        href={DOCS.storingMetadata}\n        target=\"_blank\"\n        size=\"extraLarge\"\n        sx={{ alignSelf: 'center', width: 'fit-content' }}\n        variant=\"text\"\n      >\n        {t('editMetadata.storingInformationStep2Link')}\n      </Button>\n      <Typography fontWeight={400} sx={{ textAlign: 'center' }} variant=\"body1\">\n        {t('editMetadata.storingInformationDescription')}\n      </Typography>\n      <Box sx={{ my: 4 }}>\n        <Step\n          component={\n            <Button\n              data-testid=\"metadata-download-button\"\n              onClick={onClickDownloadJson}\n              size=\"extraLarge\"\n              startIcon={<img alt=\"download\" src={ICONS.download} />}\n              sx={{\n                width: 'fit-content',\n                ml: screenWidth < 1024 ? 0 : 1.75,\n                mt: screenWidth < 1024 ? 1.5 : 0,\n              }}\n              variant=\"outlined\"\n            >\n              {`${ellipsizeText(fileName, 8)}.jsonld`}\n            </Button>\n          }\n          label={t('editMetadata.storingInformationStep1Label')}\n          componentsLayoutStyles={{\n            alignItems: screenWidth < 1024 ? undefined : 'center',\n            flexDirection: screenWidth < 1024 ? 'column' : 'row',\n          }}\n          stepNumber={1}\n        />\n        <Spacer y={6} />\n        <Step\n          layoutStyles={{ alignItems: 'center' }}\n          label={t('editMetadata.storingInformationStep2Label')}\n          stepNumber={2}\n        />\n        <Spacer y={6} />\n        <Step\n          component={\n            <ControlledField.Input\n              {...{ control, errors }}\n              dataTestId=\"metadata-url-input\"\n              layoutStyles={{ mt: 1.5 }}\n              name=\"storingURL\"\n              placeholder={t('editMetadata.storingInformationURLPlaceholder')}\n              rules={Rules.STORING_LINK}\n            />\n          }\n          label={t('editMetadata.storingInformationStep3Label')}\n          stepNumber={3}\n        />\n      </Box>\n      <TransactionStepButtons\n        onActionButton={onSubmit}\n        actionButtonText={t('submit')}\n        actionButtonDataTestId=\"submit-button\"\n        disableActionButton={isActionButtonDisabled}\n        isLoadingActionButton={isSubmitting}\n        onBackButton={onClickBack}\n      />\n    </>\n  );\n};\n","import { useState } from 'react';\nimport { FormProvider, useForm } from 'react-hook-form';\n\nimport { defaultDRepDataFormValues } from '@/hooks';\nimport { EditDRepForm } from './editMetadata/EditDRepForm';\nimport { EditDRepStoreDataInfo } from './editMetadata/EditDRepStoreDataInfo';\nimport { EditDRepStorageInformation } from './editMetadata/EditDRepStorageInformation';\n\ntype Props = {\n  onCancel: () => void;\n};\n\nexport const EditDRepMetadata = ({ onCancel }: Props) => {\n  const [step, setStep] = useState<number>(1);\n  const [loadUserData, setLoadUserData] = useState(true);\n\n  const methods = useForm({\n    mode: 'onChange',\n    defaultValues: defaultDRepDataFormValues,\n  });\n\n  return (\n    <FormProvider {...methods}>\n      {step === 1 && (\n        <EditDRepForm\n          onClickCancel={onCancel}\n          setStep={setStep}\n          loadUserData={loadUserData}\n          setLoadUserData={setLoadUserData}\n        />\n      )}\n      {step === 2 && <EditDRepStoreDataInfo setStep={setStep} />}\n      {step === 3 && <EditDRepStorageInformation setStep={setStep} />}\n    </FormProvider>\n  );\n};\n","import { Dispatch, SetStateAction } from 'react';\nimport { Trans } from 'react-i18next';\nimport { Link } from '@mui/material';\n\nimport { DOCS } from '@/consts';\nimport { useScreenDimension, useTranslation } from '@/hooks';\nimport { correctAdaFormat } from '@/utils';\nimport { usePillarContext } from '@/context';\nimport { Typography } from '@/components';\nimport { TransactionStepButtons } from '../common/TransactionStepButtons';\n\nexport const RolesAndResponsibilities = ({\n  setStep,\n}: {\n  setStep: Dispatch<SetStateAction<number>>;\n}) => {\n  const { epochParams } = usePillarContext();\n  const { t } = useTranslation();\n  const { isMobile } = useScreenDimension();\n\n  const onClickContinue = () => setStep(2);\n\n  return (\n    <>\n      <Typography sx={{ textAlign: 'center' }} variant=\"headline4\">\n        {t('registration.rolesAndResponsibilitiesTitle')}\n      </Typography>\n      <Typography\n        fontWeight={400}\n        sx={{\n          pb: isMobile ? 4 : 6,\n          pt: 4,\n          textAlign: 'center',\n          whiteSpace: 'pre-line',\n        }}\n        variant=\"body1\"\n      >\n        <Trans\n          components={[<Link key=\"1\" href={DOCS.dReps} target=\"_blank\" />]}\n          i18nKey=\"registration.rolesAndResponsibilitiesDescription\"\n          values={{ deposit: correctAdaFormat(epochParams?.drep_deposit) }}\n        />\n      </Typography>\n      <TransactionStepButtons\n        onActionButton={onClickContinue}\n        backButtonText={t('cancel')}\n      />\n    </>\n  );\n};\n","import { Dispatch, SetStateAction } from 'react';\nimport { Box } from '@mui/material';\n\nimport { useDRepDataForm, useTranslation } from '@/hooks';\nimport { VoterInfo } from '@/types';\nimport { DRepDataForm } from '../common/DRepDataForm';\nimport { TransactionStepButtons } from '../common/TransactionStepButtons';\n\nexport const RegisterAsDRepForm = ({\n  onClickCancel,\n  setStep,\n  voter,\n}: {\n  onClickCancel: () => void;\n  setStep: Dispatch<SetStateAction<number>>;\n  voter?: VoterInfo;\n}) => {\n  const { t } = useTranslation();\n  const { control, errors, isError, register, watch } = useDRepDataForm({\n    type: 'register',\n  });\n\n  const onClickContinue = () => setStep(3);\n\n  const onClickBack = () => setStep(1);\n\n  const isContinueButtonDisabled = !watch('givenName') || isError;\n\n  return (\n    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 8 }}>\n      <DRepDataForm control={control} errors={errors} register={register} />\n      <TransactionStepButtons\n        onActionButton={onClickContinue}\n        disableActionButton={isContinueButtonDisabled}\n        onBackButton={voter?.wasRegisteredAsDRep ? onClickCancel : onClickBack}\n        backButtonText={voter?.wasRegisteredAsDRep ? t('cancel') : t('back')}\n      />\n    </Box>\n  );\n};\n","import { Dispatch, SetStateAction } from 'react';\nimport { Box, Link } from '@mui/material';\n\nimport { DOCS } from '@/consts';\nimport { useDRepDataForm, useScreenDimension, useTranslation } from '@/hooks';\nimport { ControlledField, Spacer, Typography } from '@/components';\nimport { TransactionStepButtons } from '../common/TransactionStepButtons';\n\nexport const DRepStoreDataInfo = ({\n  setStep,\n}: {\n  setStep: Dispatch<SetStateAction<number>>;\n}) => {\n  const { t } = useTranslation();\n  const { isMobile } = useScreenDimension();\n  const { control, errors, watch } = useDRepDataForm({ type: 'register' });\n\n  const onClickBackButton = () => setStep(2);\n\n  const isContinueDisabled = !watch('storeData');\n\n  const onClickContinue = () => setStep(4);\n\n  return (\n    <>\n      <Typography sx={{ textAlign: 'center' }} variant=\"headline4\">\n        {t('registration.storeDataTitle')}\n      </Typography>\n      <Link\n        href={DOCS.storingMetadata}\n        target=\"_blank\"\n        sx={{\n          fontSize: 16,\n          fontWeight: 500,\n          fontFamily: 'Poppins',\n          my: 4,\n          textAlign: 'center',\n          textDecoration: 'none',\n        }}\n      >\n        {t('registration.storeDataLink')}\n      </Link>\n      <ControlledField.Checkbox\n        {...{ control, errors }}\n        name=\"storeData\"\n        label={t('registration.storeDataCheckboxLabel')}\n      />\n      <Spacer y={isMobile ? 4 : 12.5} />\n      <Box display=\"flex\" flex={1} />\n      <TransactionStepButtons\n        onActionButton={onClickContinue}\n        actionButtonText={t('register')}\n        actionButtonDataTestId=\"register-button\"\n        disableActionButton={isContinueDisabled}\n        onBackButton={onClickBackButton}\n      />\n    </>\n  );\n};\n","import { Dispatch, SetStateAction, useEffect } from 'react';\nimport { Box } from '@mui/material';\nimport OpenInNewIcon from '@mui/icons-material/OpenInNew';\n\nimport { DOCS, ICONS } from '@/consts';\nimport {\n  useTranslation,\n  useScreenDimension,\n  useDRepDataForm,\n  useRules,\n} from '@/hooks';\nimport { ellipsizeText } from '@/utils';\nimport { Button, ControlledField, Spacer, Typography } from '@/components';\nimport { Step } from '../common/Step';\nimport { TransactionStepButtons } from '../common/TransactionStepButtons';\n\ntype StorageInformationProps = {\n  setStep: Dispatch<SetStateAction<number>>;\n};\n\nexport const DRepStorageInformation = ({\n  setStep,\n}: StorageInformationProps) => {\n  const { t } = useTranslation();\n  const Rules = useRules();\n  const {\n    control,\n    errors,\n    generateMetadata,\n    getValues,\n    isSubmitting,\n    onClickDownloadJson,\n    onSubmit,\n    watch,\n  } = useDRepDataForm({ type: 'register', onCancel: () => setStep(2) });\n  const { screenWidth } = useScreenDimension();\n\n  const fileName = getValues('givenName').replace(/\\s/g, '');\n\n  const isActionButtonDisabled = !watch('storingURL') || !!errors.storingURL;\n\n  const onClickBack = () => setStep(3);\n\n  useEffect(() => {\n    generateMetadata();\n  }, []);\n\n  return (\n    <>\n      <Typography sx={{ textAlign: 'center' }} variant=\"headline4\">\n        {t('registration.storingInformationTitle')}\n      </Typography>\n      <Button\n        data-testid=\"read-guide-button\"\n        endIcon={\n          <OpenInNewIcon\n            sx={{\n              color: 'primary',\n              height: 17,\n              width: 17,\n            }}\n          />\n        }\n        href={DOCS.storingMetadata}\n        target=\"_blank\"\n        size=\"extraLarge\"\n        sx={{ alignSelf: 'center', width: 'fit-content' }}\n        variant=\"text\"\n      >\n        {t('registration.storingInformationStep2Link')}\n      </Button>\n      <Typography fontWeight={400} sx={{ textAlign: 'center' }} variant=\"body1\">\n        {t('registration.storingInformationDescription')}\n      </Typography>\n      <Box sx={{ my: 4 }}>\n        <Step\n          component={\n            <Button\n              data-testid=\"metadata-download-button\"\n              onClick={onClickDownloadJson}\n              size=\"extraLarge\"\n              startIcon={<img alt=\"download\" src={ICONS.download} />}\n              sx={{\n                width: 'fit-content',\n                ml: screenWidth < 1024 ? 0 : 1.75,\n                mt: screenWidth < 1024 ? 1.5 : 0,\n              }}\n              variant=\"outlined\"\n            >\n              {`${ellipsizeText(fileName, 8)}.jsonld`}\n            </Button>\n          }\n          label={t('registration.storingInformationStep1Label')}\n          componentsLayoutStyles={{\n            alignItems: screenWidth < 1024 ? undefined : 'center',\n            flexDirection: screenWidth < 1024 ? 'column' : 'row',\n          }}\n          stepNumber={1}\n        />\n        <Spacer y={6} />\n        <Step\n          layoutStyles={{ alignItems: 'center' }}\n          label={t('registration.storingInformationStep2Label')}\n          stepNumber={2}\n        />\n        <Spacer y={6} />\n        <Step\n          component={\n            <ControlledField.Input\n              {...{ control, errors }}\n              dataTestId=\"metadata-url-input\"\n              layoutStyles={{ mt: 1.5 }}\n              name=\"storingURL\"\n              placeholder={t('registration.storingInformationURLPlaceholder')}\n              rules={Rules.STORING_LINK}\n            />\n          }\n          label={t('registration.storingInformationStep3Label')}\n          stepNumber={3}\n        />\n      </Box>\n      <TransactionStepButtons\n        onActionButton={onSubmit}\n        actionButtonText={t('submit')}\n        actionButtonDataTestId=\"submit-button\"\n        disableActionButton={isActionButtonDisabled}\n        isLoadingActionButton={isSubmitting}\n        onBackButton={onClickBack}\n      />\n    </>\n  );\n};\n","import { useEffect, useState } from 'react';\nimport { FormProvider, useForm } from 'react-hook-form';\n\nimport { defaultDRepDataFormValues, useGetVoterInfo } from '@/hooks';\nimport { RolesAndResponsibilities } from './registerDRep/RolesAndResponsibilities';\nimport { RegisterAsDRepForm } from './registerDRep/RegisterAsDRepForm';\nimport { DRepStoreDataInfo } from './registerDRep/DRepStoreDataInfo';\nimport { DRepStorageInformation } from './registerDRep/DRepStorageInformation';\n\ntype Props = {\n  onCancel: () => void;\n};\n\nexport const RegisterAsdRep = ({ onCancel }: Props) => {\n  const [step, setStep] = useState<number>(1);\n  const { voter } = useGetVoterInfo();\n\n  const methods = useForm({\n    mode: 'onChange',\n    defaultValues: defaultDRepDataFormValues,\n  });\n\n  useEffect(() => {\n    if (voter?.wasRegisteredAsDRep) setStep(2);\n  }, [voter?.wasRegisteredAsDRep]);\n\n  return (\n    <>\n      {step === 1 && !voter?.wasRegisteredAsDRep && (\n        <RolesAndResponsibilities setStep={setStep} />\n      )}\n      <FormProvider {...methods}>\n        {step === 2 && (\n          <RegisterAsDRepForm\n            onClickCancel={onCancel}\n            setStep={setStep}\n            voter={voter}\n          />\n        )}\n        {step === 3 && <DRepStoreDataInfo setStep={setStep} />}\n        {step === 4 && <DRepStorageInformation setStep={setStep} />}\n      </FormProvider>\n    </>\n  );\n};\n","import { Trans } from 'react-i18next';\nimport { Link } from '@mui/material';\n\nimport { DOCS } from '@/consts';\nimport { useRegisterVoter, useScreenDimension, useTranslation } from '@/hooks';\nimport { correctAdaFormat } from '@/utils';\nimport { Typography } from '@/components';\nimport { usePillarContext } from '@/context';\nimport { TransactionStepButtons } from './common/TransactionStepButtons';\n\nexport const RegisterAsDirectVoter = () => {\n  const { epochParams } = usePillarContext();\n  const { t } = useTranslation();\n  const { isMobile } = useScreenDimension();\n\n  const { registerVoter, isRegistering } = useRegisterVoter();\n\n  return (\n    <>\n      <Typography sx={{ mt: 1, textAlign: 'center' }} variant=\"headline4\">\n        {t('directVoter.registerHeading')}\n      </Typography>\n      <Typography\n        fontWeight={400}\n        sx={{\n          mb: 7,\n          mt: isMobile ? 4 : 10,\n          textAlign: 'center',\n          whiteSpace: 'pre-line',\n        }}\n        variant=\"body1\"\n      >\n        <Trans\n          i18nKey=\"directVoter.registerDescription\"\n          values={{ deposit: correctAdaFormat(epochParams?.drep_deposit) }}\n          components={[\n            <Link href={DOCS.directVoting} target=\"_blank\" key=\"0\" />,\n          ]}\n        />\n      </Typography>\n      <TransactionStepButtons\n        onActionButton={registerVoter}\n        isLoadingActionButton={isRegistering}\n        backButtonText={t('cancel')}\n      />\n    </>\n  );\n};\n","import { useEffect } from 'react';\nimport * as Sentry from '@sentry/react';\n\nimport { useRetireVoter, useScreenDimension, useTranslation } from '@/hooks';\nimport { Typography } from '@/components';\nimport { TransactionStepButtons } from './common/TransactionStepButtons';\n\nexport const RetireAsDRep = ({\n  onClickCancel,\n}: {\n  onClickCancel: () => void;\n}) => {\n  const { t } = useTranslation();\n  const { isMobile } = useScreenDimension();\n\n  const { retireVoter, isRetiring } = useRetireVoter();\n\n  useEffect(() => {\n    Sentry.setTag('component_name', 'WhatRetirementMeans');\n  }, []);\n\n  return (\n    <>\n      <Typography sx={{ textAlign: 'center' }} variant=\"headline4\">\n        {t('retirement.whatRetirementMeansTitle')}\n      </Typography>\n      <Typography\n        fontWeight={400}\n        sx={{\n          pb: isMobile ? 4 : 6,\n          pt: 4,\n          textAlign: 'center',\n          whiteSpace: 'pre-line',\n        }}\n        variant=\"body1\"\n      >\n        {t('retirement.whatRetirementMeansDescription')}\n      </Typography>\n      <TransactionStepButtons\n        actionButtonText={t('retirement.continue')}\n        actionButtonDataTestId=\"continue-retirement-button\"\n        backButtonText={t('cancel')}\n        isLoadingActionButton={isRetiring}\n        onActionButton={() => retireVoter('Drep')}\n        onBackButton={onClickCancel}\n      />\n    </>\n  );\n};\n","import { Trans } from 'react-i18next';\nimport { Link } from '@mui/material';\n\nimport { DOCS } from '@/consts';\nimport {\n  useGetVoterInfo,\n  useRetireVoter,\n  useScreenDimension,\n  useTranslation,\n} from '@/hooks';\nimport { correctAdaFormat } from '@/utils';\nimport { Typography } from '@/components';\nimport { TransactionStepButtons } from './common/TransactionStepButtons';\n\nexport const RetireAsDirectVoter = () => {\n  const { t } = useTranslation();\n  const { isMobile } = useScreenDimension();\n  const { voter } = useGetVoterInfo();\n\n  const { retireVoter, isRetiring } = useRetireVoter();\n\n  return (\n    <>\n      <Typography sx={{ mt: 1, textAlign: 'center' }} variant=\"headline4\">\n        {t('directVoter.retirementHeading')}\n      </Typography>\n      <Typography\n        fontWeight={400}\n        sx={{\n          mb: 7,\n          mt: isMobile ? 4 : 10,\n          textAlign: 'center',\n          whiteSpace: 'pre-line',\n        }}\n        variant=\"body1\"\n      >\n        <Trans\n          i18nKey=\"directVoter.retirementDescription\"\n          values={{ deposit: correctAdaFormat(voter?.deposit) }}\n          components={[\n            <Link\n              href={DOCS.functions}\n              target=\"_blank\"\n              sx={{ textDecoration: 'none' }}\n              key=\"0\"\n            />,\n          ]}\n        />\n      </Typography>\n      <TransactionStepButtons\n        onActionButton={() => retireVoter('DirectVoter')}\n        isLoadingActionButton={isRetiring}\n        backButtonText={t('cancel')}\n      />\n    </>\n  );\n};\n","import { FC, PropsWithChildren } from 'react';\nimport { Box } from '@mui/material';\n\nimport { useScreenDimension } from '@/hooks';\nimport { voltaireTheme as theme } from '@/theme';\n\ninterface Props {\n  hideBox?: boolean;\n}\nexport const TransactionBox: FC<PropsWithChildren<Props>> = ({\n  hideBox,\n  children,\n}) => {\n  const { isMobile } = useScreenDimension();\n  const {\n    palette: { boxShadow2 },\n  } = theme;\n\n  if (hideBox)\n    return (\n      <Box\n        flex={1}\n        display=\"flex\"\n        flexDirection=\"column\"\n        alignItems=\"center\"\n        justifyContent=\"center\"\n      >\n        {children}\n      </Box>\n    );\n\n  return (\n    <Box\n      alignSelf=\"center\"\n      borderRadius=\"20px\"\n      boxShadow={isMobile ? '' : `2px 2px 20px 0px ${boxShadow2}`}\n      boxSizing=\"border-box\"\n      mb={isMobile ? 2 : 1.5}\n      px={isMobile ? 2 : 18.75}\n      py={isMobile ? 6 : 8}\n      height=\"auto\"\n      width=\"100%\"\n      maxWidth={isMobile ? 'none' : 900}\n      display=\"flex\"\n      flexDirection=\"column\"\n    >\n      {children}\n    </Box>\n  );\n};\n","import { useNavigate } from 'react-router-dom';\nimport { Box } from '@mui/material';\n\nimport { Button, Typography } from '@/components';\nimport { useScreenDimension, useTranslation } from '@/hooks';\nimport { PATHS } from '@/consts';\n\ntype Props = {\n  title?: string;\n  description?: string;\n  primaryButtonText?: string;\n  secondaryButtonText?: string;\n  onPrimaryButton?: () => void;\n  onSecondaryButton?: () => void;\n  hideSecondaryButton?: boolean;\n};\n\nexport const WrongRouteInfo = ({\n  title,\n  description,\n  primaryButtonText,\n  secondaryButtonText,\n  hideSecondaryButton,\n  onPrimaryButton,\n  onSecondaryButton,\n}: Props) => {\n  const { t } = useTranslation();\n  const { isMobile } = useScreenDimension();\n  const navigate = useNavigate();\n\n  const primaryButtonProps = {\n    children: primaryButtonText ?? t('backToDashboard'),\n    onClick: onPrimaryButton ?? (() => navigate(PATHS.dashboard)),\n  };\n\n  const secondaryButtonProps =\n    primaryButtonText || onPrimaryButton\n      ? {\n          children: secondaryButtonText ?? t('backToDashboard'),\n          onClick: onSecondaryButton ?? (() => navigate(PATHS.dashboard)),\n        }\n      : undefined;\n\n  return (\n    <>\n      {title && (\n        <Typography sx={{ textAlign: 'center' }} variant=\"headline4\">\n          {title}\n        </Typography>\n      )}\n      {description && (\n        <Typography\n          fontWeight={400}\n          sx={{\n            pb: isMobile ? 4 : 6,\n            pt: 4,\n            textAlign: 'center',\n            whiteSpace: 'pre-line',\n          }}\n          variant=\"body1\"\n        >\n          {description}\n        </Typography>\n      )}\n\n      <Box\n        sx={{\n          display: 'flex',\n          flexDirection: isMobile ? 'column-reverse' : 'row',\n          gap: 3,\n          justifyContent: secondaryButtonProps ? 'space-between' : 'center',\n        }}\n      >\n        {!hideSecondaryButton && secondaryButtonProps && (\n          <Button\n            data-testid=\"secondary-button\"\n            size=\"extraLarge\"\n            sx={{\n              px: 6,\n            }}\n            variant=\"outlined\"\n            {...secondaryButtonProps}\n          />\n        )}\n        <Button\n          data-testid=\"primary-button\"\n          size=\"extraLarge\"\n          sx={{\n            px: 6,\n          }}\n          variant=\"contained\"\n          {...primaryButtonProps}\n        />\n      </Box>\n    </>\n  );\n};\n","import { Box } from '@mui/material';\n\nimport { usePillarContext } from '@/context';\nimport {\n  useGetAdaHolderCurrentDelegationQuery,\n  useGetDRepDetailsQuery,\n} from '@/hooks';\nimport { isSameDRep } from '@/utils';\nimport { CircularLoader } from '@/components';\nimport { EmptyStateDrepDirectory, DRepDetailsCard } from '@/features';\n\nexport const DRepDetailsPage = () => {\n  const {\n    dRepID: myDRepId,\n    pendingTransaction,\n    stakeKey,\n    useParams,\n  } = usePillarContext();\n  const { id } = useParams('id');\n  const { currentDelegation } = useGetAdaHolderCurrentDelegationQuery(stakeKey);\n\n  const { dRep, isLoading } = useGetDRepDetailsQuery(id);\n\n  if (isLoading) return <CircularLoader />;\n\n  if (!dRep)\n    return (\n      <Box\n        sx={{\n          alignItems: 'center',\n          display: 'flex',\n          flex: 1,\n          justifyContent: 'center',\n        }}\n      >\n        <EmptyStateDrepDirectory />\n      </Box>\n    );\n\n  return (\n    <DRepDetailsCard\n      dRepData={dRep}\n      isMe={isSameDRep(dRep, myDRepId)}\n      isMyDrep={isSameDRep(dRep, currentDelegation?.dRepView)}\n      isMyDrepInProgress={isSameDRep(\n        dRep,\n        pendingTransaction.delegate?.resourceId\n      )}\n    />\n  );\n};\n","import { FC } from 'react';\nimport { Box } from '@mui/material';\n\nimport { AutomatedVotingOptions, MyDelegation, DRepList } from '@/features';\nimport { usePillarContext } from '@/context';\nimport {\n  useDelegateTodRep,\n  useGetAdaHolderCurrentDelegationQuery,\n  useGetAdaHolderVotingPowerQuery,\n  useGetDRepDetailsQuery,\n} from '@/hooks';\nimport { correctAdaFormat } from '@/utils';\nimport { CircularLoader } from '@/components';\n\nexport const DRepDirectoryPage: FC = () => {\n  const {\n    pendingTransaction,\n    stakeKey,\n    isEnabled: isConnected,\n  } = usePillarContext();\n\n  const { delegate, isDelegating } = useDelegateTodRep();\n\n  const { votingPower } = useGetAdaHolderVotingPowerQuery(stakeKey);\n  const { currentDelegation } = useGetAdaHolderCurrentDelegationQuery(stakeKey);\n  const inProgressDelegation = pendingTransaction.delegate?.resourceId;\n\n  const { dRep: myDrep } = useGetDRepDetailsQuery(currentDelegation?.dRepView, {\n    enabled: !!inProgressDelegation || !!currentDelegation,\n  });\n\n  if (\n    (stakeKey && votingPower === undefined) ||\n    (isConnected && currentDelegation === undefined)\n  ) {\n    return <CircularLoader />;\n  }\n\n  const ada = correctAdaFormat(votingPower);\n\n  return (\n    <Box display=\"flex\" flex={1} flexDirection=\"column\" gap={4}>\n      <MyDelegation dRep={myDrep} />\n\n      {isConnected && (\n        <AutomatedVotingOptions\n          currentDelegation={\n            !pendingTransaction.delegate\n              ? currentDelegation?.dRepView\n              : undefined\n          }\n          delegate={delegate}\n          delegationInProgress={inProgressDelegation}\n          isDelegationLoading={isDelegating}\n          votingPower={ada.toString()}\n          pendingTransaction={pendingTransaction}\n          txHash={\n            !pendingTransaction.delegate ? currentDelegation?.txHash : undefined\n          }\n        />\n      )}\n\n      <DRepList />\n    </Box>\n  );\n};\n","import { Navigate, useLocation } from 'react-router-dom';\nimport { CircularProgress } from '@mui/material';\n\nimport { PATHS } from '@/consts';\nimport { useGetVoterInfo, useAbandonWarningModal } from '@/hooks';\nimport { TransactionBox, EditDRepMetadata } from '@/features';\n\nexport const EditDRepMetadataPage = () => {\n  const { state } = useLocation();\n  const { voter } = useGetVoterInfo({ enabled: !state });\n  const openAbandonWarningModal = useAbandonWarningModal();\n\n  if (voter && !voter?.isRegisteredAsDRep)\n    return <Navigate to={PATHS.dashboard} />;\n\n  return (\n    <TransactionBox>\n      {!voter?.isRegisteredAsDRep ? (\n        <CircularProgress />\n      ) : (\n        <EditDRepMetadata onCancel={openAbandonWarningModal} />\n      )}\n    </TransactionBox>\n  );\n};\n","\"use client\";\n\nimport createSvgIcon from \"./utils/createSvgIcon.js\";\nimport { jsx as _jsx } from \"react/jsx-runtime\";\nexport default createSvgIcon(/*#__PURE__*/_jsx(\"path\", {\n  d: \"M3 18h18v-2H3zm0-5h18v-2H3zm0-7v2h18V6z\"\n}), 'Menu');","import { useState, MouseEvent } from 'react';\nimport { Link, Outlet, matchPath, useLocation } from 'react-router-dom';\nimport {\n  AppBar,\n  Box,\n  IconButton,\n  Menu,\n  MenuItem,\n  Toolbar,\n} from '@mui/material';\nimport MenuIcon from '@mui/icons-material/Menu';\n\nimport { Typography } from '@/components';\nimport { PATHS } from '@/consts';\n\nconst EXCLUDED_PATHS = ['home', 'dashboard', 'dRepDetails', 'editDRepMetadata'];\n\nexport const Features = () => {\n  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);\n  const open = Boolean(anchorEl);\n  const handleClick = (event: MouseEvent<HTMLButtonElement>) => {\n    setAnchorEl(event.currentTarget);\n  };\n  const handleClose = () => {\n    setAnchorEl(null);\n  };\n\n  const { pathname } = useLocation();\n\n  const pathKey = Object.entries(PATHS).find(([, pattern]) =>\n    matchPath(`demo/${pattern}`, pathname)\n  )?.[0];\n\n  return (\n    <Box\n      sx={{\n        minHeight: '100vh',\n        display: 'flex',\n        flexDirection: 'column',\n        alignItems: 'center',\n        justifyContent: 'center',\n        background: `\n        radial-gradient(ellipse at 0vw 20vh, rgba(214, 226, 255, 0.5) 0%, rgba(214, 226, 255, 0.5) 20%, transparent 40%),\n        radial-gradient(ellipse at 80% 90%, rgba(255, 203, 173, 0.5) 0%, rgba(255, 203, 173, 0.4) 20%, transparent 40%)`,\n        backgroundRepeat: 'no-repeat',\n        backgroundAttachment: 'fixed',\n      }}\n    >\n      <AppBar position=\"fixed\" sx={{ borderRadius: 0 }}>\n        <Toolbar sx={{ gap: 2 }}>\n          <Link to=\"/home\" style={{ textDecoration: 'none' }}>\n            <Typography variant=\"headline5\" color=\"#fff\">\n              Delegation Pillar\n            </Typography>\n          </Link>\n          <Typography variant=\"title2\" color=\"#fff9\">\n            {'/ '}\n            {pathKey}\n          </Typography>\n          <IconButton\n            id=\"basic-button\"\n            edge=\"end\"\n            aria-controls={open ? 'basic-menu' : undefined}\n            aria-haspopup=\"true\"\n            aria-expanded={open ? 'true' : undefined}\n            onClick={handleClick}\n            sx={{ ml: 'auto' }}\n          >\n            <MenuIcon htmlColor=\"#fff\" />\n          </IconButton>\n          <Menu\n            id=\"basic-menu\"\n            anchorEl={anchorEl}\n            open={open}\n            onClose={handleClose}\n            MenuListProps={{\n              'aria-labelledby': 'basic-button',\n            }}\n          >\n            {Object.entries(PATHS)\n              .filter(([key]) => !EXCLUDED_PATHS.includes(key))\n              .map(([key, path]) => (\n                <MenuItem key={key} component={Link} to={path}>\n                  {key}\n                </MenuItem>\n              ))}\n          </Menu>\n        </Toolbar>\n      </AppBar>\n\n      <Box\n        sx={{\n          p: 6,\n          pt: 12,\n          width: '100%',\n          maxWidth: '100%',\n          display: 'flex',\n          flexDirection: 'column',\n          flex: 1,\n        }}\n      >\n        <Outlet />\n      </Box>\n\n      <Box\n        sx={(theme) => ({\n          width: '100%',\n          backgroundColor: theme.palette.boxShadow2,\n          px: 3,\n          py: 1,\n          mt: 'auto',\n        })}\n      >\n        <Typography variant=\"caption\">© 2024 Intersect MBO</Typography>\n      </Box>\n    </Box>\n  );\n};\n","import { Box, MenuItem, MenuList } from '@mui/material';\nimport { Link } from 'react-router-dom';\n\nimport { Card, Typography } from '@/components';\nimport { PATHS } from '@/consts';\n\nconst EXCLUDED_PATHS = ['home', 'dashboard', 'dRepDetails', 'editDRepMetadata'];\n\nexport const IntroPage = () => {\n  return (\n    <Box\n      sx={{\n        height: '100vh',\n        display: 'flex',\n        flexDirection: 'column',\n        alignItems: 'center',\n        justifyContent: 'center',\n        gap: 6,\n        pb: '10vh',\n        background: `\n        radial-gradient(circle, rgba(214, 226, 255, 1) 0%, transparent 70%),\n        radial-gradient(circle, rgba(255, 203, 173, 0.8) 0%, transparent 70%)`,\n        backgroundPosition: '-20vw -20vh, 30vw 15vh',\n      }}\n    >\n      <Typography variant=\"headline2\" color=\"primary\">\n        Delegation Pillar\n      </Typography>\n      <Card sx={{ p: 0 }}>\n        <MenuList sx={{ color: '#000' }}>\n          {Object.entries(PATHS)\n            .filter(([key]) => !EXCLUDED_PATHS.includes(key))\n            .map(([key, path]) => (\n              <MenuItem\n                key={key}\n                component={Link}\n                to={`/demo/${path}`}\n                sx={{ px: 6, py: 1.5 }}\n              >\n                {key}\n              </MenuItem>\n            ))}\n        </MenuList>\n      </Card>\n    </Box>\n  );\n};\n","import { CircularProgress } from '@mui/material';\n\nimport { PATHS } from '@/consts';\nimport { usePillarContext } from '@/context';\nimport {\n  useTranslation,\n  useGetVoterInfo,\n  useGetDRepDetailsQuery,\n  useAbandonWarningModal,\n} from '@/hooks';\nimport { TransactionBox, WrongRouteInfo, RegisterAsdRep } from '@/features';\n\nexport const RegisterAsdRepPage = () => {\n  const { dRepID, useRouter } = usePillarContext();\n  const { t } = useTranslation();\n  const { voter } = useGetVoterInfo();\n  const { dRep } = useGetDRepDetailsQuery(dRepID);\n  const openAbandonWarningModal = useAbandonWarningModal();\n\n  const router = useRouter();\n\n  if (!voter)\n    return (\n      <TransactionBox hideBox>\n        <CircularProgress />\n      </TransactionBox>\n    );\n\n  if (voter.isRegisteredAsDRep)\n    return (\n      <TransactionBox>\n        <WrongRouteInfo\n          title={t(`registration.alreadyRegistered.title`)}\n          description={t(`registration.alreadyRegistered.description`)}\n          primaryButtonText={t('registration.alreadyRegistered.viewDetails')}\n          onPrimaryButton={() => {\n            if (!dRep) return;\n\n            router.push(\n              `../${PATHS.dRepDetails}`.replace(':dRepId', dRep.view)\n            );\n          }}\n        />\n      </TransactionBox>\n    );\n\n  return (\n    <TransactionBox>\n      <RegisterAsdRep onCancel={openAbandonWarningModal} />\n    </TransactionBox>\n  );\n};\n","import { CircularProgress } from '@mui/material';\n\nimport { useGetVoterInfo, useTranslation } from '@/hooks';\nimport {\n  RegisterAsDirectVoter,\n  TransactionBox,\n  WrongRouteInfo,\n} from '@/features';\n\nexport const RegisterAsDirectVoterPage = () => {\n  const { t } = useTranslation();\n  const { voter } = useGetVoterInfo();\n\n  if (!voter)\n    return (\n      <TransactionBox hideBox>\n        <CircularProgress />\n      </TransactionBox>\n    );\n\n  if (voter?.isRegisteredAsSoleVoter)\n    return (\n      <TransactionBox>\n        <WrongRouteInfo\n          title={t(`directVoter.alreadyRegistered.title`)}\n          description={t(`directVoter.alreadyRegistered.description`)}\n        />\n      </TransactionBox>\n    );\n\n  return (\n    <TransactionBox>\n      <RegisterAsDirectVoter />\n    </TransactionBox>\n  );\n};\n","import { useNavigate } from 'react-router-dom';\nimport { CircularProgress } from '@mui/material';\n\nimport { PATHS } from '@/consts';\nimport { useGetVoterInfo, useTranslation } from '@/hooks';\nimport { WrongRouteInfo, TransactionBox, RetireAsDRep } from '@/features';\n\nexport const RetireAsDRepPage = () => {\n  const navigate = useNavigate();\n  const { t } = useTranslation();\n  const { voter } = useGetVoterInfo();\n\n  const onClickBackToDashboard = () => navigate(PATHS.dashboard);\n\n  if (!voter)\n    return (\n      <TransactionBox hideBox>\n        <CircularProgress />\n      </TransactionBox>\n    );\n\n  return (\n    <TransactionBox>\n      {!voter.isRegisteredAsDRep ? (\n        <WrongRouteInfo\n          title={t('retirement.notADRep.title')}\n          description={t('retirement.notADRep.description')}\n        />\n      ) : (\n        <RetireAsDRep onClickCancel={onClickBackToDashboard} />\n      )}\n    </TransactionBox>\n  );\n};\n","import { CircularProgress } from '@mui/material';\n\nimport { useGetVoterInfo, useTranslation } from '@/hooks';\nimport {\n  TransactionBox,\n  WrongRouteInfo,\n  RetireAsDirectVoter,\n} from '@/features';\n\nexport const RetireAsDirectVoterPage = () => {\n  const { t } = useTranslation();\n  const { voter } = useGetVoterInfo();\n\n  if (!voter)\n    return (\n      <TransactionBox hideBox>\n        <CircularProgress />\n      </TransactionBox>\n    );\n\n  if (!voter.isRegisteredAsSoleVoter)\n    return (\n      <TransactionBox>\n        <WrongRouteInfo\n          title={t('directVoter.notDirectVoter.title')}\n          description={t('directVoter.notDirectVoter.description')}\n        />\n      </TransactionBox>\n    );\n\n  return (\n    <TransactionBox>\n      <RetireAsDirectVoter />\n    </TransactionBox>\n  );\n};\n","import { Routes, Route, Outlet } from 'react-router-dom';\nimport { PATHS } from '@/consts';\nimport { usePillarContext } from '@/context';\nimport {\n  DRepDirectoryPage,\n  DRepDetailsPage,\n  EditDRepMetadataPage,\n  RegisterAsdRepPage,\n  RetireAsDRepPage,\n  RegisterAsDirectVoterPage,\n  RetireAsDirectVoterPage,\n} from '@/pages';\n\nexport const DelegationPillarRoutes = () => {\n  const { isEnabled } = usePillarContext();\n\n  return (\n    <Routes>\n      <Route path={PATHS.dRepDirectory} element={<Outlet />}>\n        <Route path=\"\" element={<DRepDirectoryPage />} />\n        <Route path=\":dRepId\" element={<DRepDetailsPage />} />\n      </Route>\n      {isEnabled && (\n        <>\n          <Route\n            path={PATHS.editDRepMetadata}\n            element={<EditDRepMetadataPage />}\n          />\n          <Route path={PATHS.registerAsDRep} element={<RegisterAsdRepPage />} />\n          <Route path={PATHS.retireAsDrep} element={<RetireAsDRepPage />} />\n          <Route\n            path={PATHS.registerAsDirectVoter}\n            element={<RegisterAsDirectVoterPage />}\n          />\n          <Route\n            path={PATHS.retireAsDirectVoter}\n            element={<RetireAsDirectVoterPage />}\n          />\n        </>\n      )}\n    </Routes>\n  );\n};\n","import { BrowserRouter } from 'react-router-dom';\nimport { ThemeProvider } from '@mui/material/styles';\nimport { QueryClient, QueryClientProvider } from 'react-query';\nimport { CssBaseline } from '@mui/material';\nimport { voltaireTheme } from '@/theme';\nimport {\n  DataActionsBarProvider,\n  ModalProvider,\n  PillarProvider,\n  PillarProviderProps,\n} from '@/context';\nimport { DelegationPillarRoutes } from './DelegationPillarRoutes';\n\nconst DelegationPillar = ({\n  walletApi,\n  apiUrl,\n  validationApiUrl,\n  routePath,\n  ...props\n}: PillarProviderProps) => {\n  return (\n    <PillarProvider\n      {...props}\n      walletApi={walletApi}\n      apiUrl={apiUrl}\n      validationApiUrl={validationApiUrl}\n    >\n      <QueryClientProvider client={new QueryClient()}>\n        <ThemeProvider theme={voltaireTheme}>\n          <ModalProvider>\n            <DataActionsBarProvider>\n              <CssBaseline />\n              <BrowserRouter basename={routePath}>\n                <DelegationPillarRoutes />\n              </BrowserRouter>\n            </DataActionsBarProvider>\n          </ModalProvider>\n        </ThemeProvider>\n      </QueryClientProvider>\n    </PillarProvider>\n  );\n};\n\nexport default DelegationPillar;\n","import { PropsWithChildren } from 'react';\nimport { ThemeProvider } from '@mui/material/styles';\nimport { voltaireTheme } from '.';\n\nexport const ThemeWrapper = ({ children }: PropsWithChildren) => (\n  <ThemeProvider theme={voltaireTheme}>{children}</ThemeProvider>\n);\n"],"names":["voidElements","t","n","r","i","e","s","a","c","o","l","m","u","f","h","p","d","v","g","warn","i18n","code","msg","rest","args","_b","_a","isString","_d","_c","alreadyWarned","warnOnce","loadedClb","cb","initialized","loadNamespaces","ns","loadLanguages","lng","hasLoadedNamespace","options","i18nInstance","loadNotPending","obj","isObject","matchHtmlEntity","htmlEntities","unescapeHtmlEntity","unescape","text","defaultOptions","setDefaults","getDefaults","setI18n","instance","getI18n","hasChildren","node","checkLength","base","getChildren","children","getAsArray","hasValidReactChildren","isValidElement","data","mergeProps","source","target","newTarget","nodesToString","i18nOptions","i18nKey","stringNode","childrenArray","keepArray","child","childIndex","props","type","childPropsCount","shouldKeepChild","childChildren","content","format","clone","keys","value","renderNodes","targetString","combinedTOpts","shouldUnescape","emptyChildrenButNeedsHandling","keep","getData","childs","ast","HTML","opts","renderInner","rootReactNode","mappedChildren","mapAST","pushTranslatedJSX","inner","mem","isVoid","cloneElement","Children","createElement","reactNode","astNode","reactNodes","translationContent","tmp","isElement","isValidTranslationWithChildren","isEmptyTransWithHTML","isKnownComponent","wrapTextNodes","result","fixComponentProps","component","index","translation","componentKey","comp","Componentized","Fragment","generateArrayComponents","components","generateObjectComponents","componentMap","generateComponents","Trans","count","parent","context","tOptions","values","defaults","i18nFromProps","tFromProps","additionalProps","k","reactI18nextOptions","names